        // 解决：添加移动冷却，让部队移动一格后等待一段时间再移动下一格
        private float _moveStepCooldown = 0f; // 移动步骤冷却（秒）
        private const float MOVE_STEP_INTERVAL = 0.2f; // 每格移动间隔（秒）


