        public virtual void AI()
        {
            if (this.Destroyed) return; // 只有销毁了才彻底不动

            // ========================================
            // 🎯 状态锁防线：只要不在 None 状态，绝对不进行大脑思考
            // ========================================
            switch (_actionLock)
            {
                case ActionLockState.WaitingForPath:
                    // 正在等待异步寻路结果，本帧直接交出 CPU
                    return;
                
                case ActionLockState.MovingOnMap:
                    // 正在执行物理移动，检查是否完成
                    if (CheckMovementCompleted())
                    {
                        // 移动完成，处理后续计划（攻击/战法）
                        ProcessPlanAfterMovement();
                    }
                    return;
                
                case ActionLockState.PlayingAnimation:
                    // 正在播放动画，检查是否播放完毕
                    if (CheckCurrentAnimationFinished())
                    {
                        // 动画播放完毕，解除锁定
                        _actionLock = ActionLockState.None;
                        _pendingCombatPlan = null;
                    }
                    return;
            }

            // 【新异步系统】兼容性检查：如果正在等路径
            if (_isWaitingForPath)
            {
                _actionLock = ActionLockState.WaitingForPath; // 同步状态
                return;
            }

            // 【新异步系统】消费阶段：如果外卖到了，直接开始走
            // ✅ Anti-Band-Aid：_cachedPath 初始化为 []，永远不为 null
            // 如果为 null，说明部队已销毁但仍在执行 AI，应该在 Destroyed 检查中捕获
            if (_cachedPath.Count > 0)
            {
                // TODO: 执行物理移动逻辑
                // ExecutePhysicalMovement();
                // 暂时先清空路径，避免死循环
                // _cachedPath.Clear();
                // return;
            }

            // 0. 势力记忆更新（低频率，避免性能问题）
            // 使用ID错峰，避免所有部队同时更新
            if ((Session.Current.Scenario.Date.Day + this.ID) % 5 == 0) // 每5天更新一次，且部队错峰
            {
                UpdateFactionMemory();
            }

            // 🔥 修复：玩家手动控制的部队不执行 AI 自动分配军团逻辑
            // 日期：2026-03-07
            // 原因：玩家部队应该在创建时或玩家下达指令时分配到 PlayerManual 军团
            //       AI() 方法中的自动分配逻辑会错误地将玩家部队分配到 AI 军团
            // 解决：玩家部队跳过 AI 自动分配逻辑
            if (this.BelongedLegion == null && this.BelongedFaction != null) 
            {
                if (this.ManualControl)
                {
                    // 🔥 数据修复：如果 StartingArchitecture 无效，使用势力的第一个有效城市
                    // 日期：2026-03-07
                    // 原因：存档加载时，StartingArchitecture 可能为 null（ID=-1 或建筑不存在）
                    // 解决：提供数据修复机制，但如果势力没有任何城市，让它崩溃
                    
                    Architecture playerBase = this.StartingArchitecture;
                    
                    // 数据修复：如果 StartingArchitecture 无效，查找势力的第一个有效城市
                    if (playerBase == null || playerBase.ID <= 0)
                    {
                        #if DEBUG
                        System.Diagnostics.Debug.WriteLine($"[TroopAI] ⚠️ 玩家部队 {this.DisplayName}(ID:{this.ID}) StartingArchitecture 无效（{playerBase?.Name ?? "null"}, ID={playerBase?.ID ?? -1}），尝试修复...");
                        #endif
                        
                        // 🔥 性能优化：使用 for 循环避免分配（Hot Path）
                        ArchitectureList archList = this.BelongedFaction.Architectures;
                        for (int i = 0; i < archList.Count; i++)
                        {
                            Architecture arch = (Architecture)archList[i];
                            if (arch.ID > 0)
                            {
                                playerBase = arch;
                                // 🔥 数据修复：同步更新 StartingArchitecture
                                this.StartingArchitecture = arch;
                                
                                #if DEBUG
                                System.Diagnostics.Debug.WriteLine($"[TroopAI] ✅ 修复成功：使用 {arch.Name}(ID:{arch.ID}) 作为出发城市");
                                #endif
                                break;
                            }
                        }
                    }
                    
                    // 🔥 Anti-Band-Aid：如果仍然无效，让它崩溃暴露问题
                    if (playerBase == null || playerBase.ID <= 0)
                    {
                        throw new InvalidOperationException(
                            $"[TroopAI] ❌ 数据错误：玩家部队 {this.DisplayName}(ID:{this.ID}) 无法找到有效的基地城市。" +
                            $"StartingArchitecture={this.StartingArchitecture?.Name ?? "null"}(ID={this.StartingArchitecture?.ID ?? -1}), " +
                            $"势力：{this.BelongedFaction.Name}，城市数：{this.BelongedFaction.Architectures.Count}");
                    }
                    
                    // 验证通过，分配军团
                    this.BelongedLegion = this.BelongedFaction.GetOrCreatePlayerLegion(playerBase);
                    
                    #if DEBUG
                    System.Diagnostics.Debug.WriteLine($"[TroopAI] 玩家部队 {this.DisplayName} 分配到 PlayerManual 军团（基地：{playerBase.Name}, ID:{playerBase.ID}）");
                    #endif
                }
                else
                {
                    // AI 控制部队：执行原有的自动分配逻辑
                    Faction belongedFaction = this.BelongedFaction;
                    Architecture targetArch = this.WillArchitecture ?? this.StartingArchitecture;
                    if (targetArch != null)
                    {
                        this.BelongedLegion = belongedFaction.GetLegion(targetArch);
                    
                    // 🔥 双向检测：如果GetLegion返回null，说明没有合适的军团
                    if (this.BelongedLegion == null)
                    {
                        // System.Diagnostics.Debug.WriteLine($"[TroopAI] 提示：部队 {this.DisplayName}(ID:{this.ID}) 未分配军团，尝试自动分配... 目标：{targetArch?.Name ?? "无"}");
                        
                        // 1. 如果已经在撤退军团中，绝对不要重新分配军团！
                        if (this.BelongedLegion != null && this.BelongedLegion.IsRetreating())
                        {
                            // 保持现有状态，直接跳过分配逻辑
                        }
                        // 2. 只有在没有军团，或者军团无效时才分配
                        else if (this.BelongedLegion == null)
                        {
                            // 如果当前状态是撤退（可能刚从军团里掉出来），优先找撤退军团
                            if (this.CurrentAIState == TroopAIState.Retreating)
                            {
                                Architecture retreatTarget = targetArch;
                                if (retreatTarget != null)
                                {
                                    this.BelongedLegion = belongedFaction.GetOrCreateLegion(retreatTarget, LegionKind.AI, LegionMission.Retreat);
                                    this.IsRetreating = true; // 🔥 修复：必须设置撤退标志，否则军团会被CleanupCompletedLegions立即解散
                                }
                            }
                            else 
                            {
                                this.BelongedLegion = belongedFaction.GetOrCreateDefaultLegion(targetArch);
                            }
                        }
                        
                        if (this.BelongedLegion == null)
                        {
                            System.Diagnostics.Debug.WriteLine($"[TroopAI] 严重错误：部队 {this.DisplayName}(ID:{this.ID}) 仍然无法分配军团，强制设为待命状态");
                            this.CurrentAIState = TroopAIState.Idle;
                            return;
                        }
                        else
                        {
                            // ★★★ 修复3：移除自动添加回军团的逻辑，避免干扰军团切换 ★★★
                            // 如果部队不在军团列表中，说明正在进行军团切换，不应该强制添加回去

                            // 🔥 修复：自动分配由于是事后补救，可能导致RealDestination未初始化 (-1,-1)
                            // 必须在这里强制初始化一次，否则会因为“无效目的地”而立即停止
                            if (!this.BelongedLegion.Troops.HasGameObject(this))
                            {
                                this.BelongedLegion.AddTroop(this);
                            }
                            if (this.RealDestination.X < 0 || this.RealDestination.Y < 0)
                            {
                                if (this.BelongedLegion.WillArchitecture != null)
                                {
                                    this.RealDestination = this.BelongedLegion.WillArchitecture.Position;
                                    // System.Diagnostics.Debug.WriteLine($"[TroopAI] 修复：强制初始化 RealDestination -> {this.RealDestination}");
                                }
                            }
                        }
                    }
                }
                else
                {
                    System.Diagnostics.Debug.WriteLine($"[TroopAI] 严重错误：部队 {this.DisplayName}(ID:{this.ID}) 没有目标建筑和起始建筑，无法分配军团");
                    this.CurrentAIState = TroopAIState.Idle;
                    return;
                }
            }
            } // 🔥 修复：闭合 if (targetArch != null) 的括号

            // ★★★ 修复3：移除双向检测代码，避免干扰军团切换 ★★★
            // 军团切换时，部队会暂时不在旧军团列表中，这是正常的

            // 2. 战略层：解析军团命令
            UpdateLegionMandate();

            // 3. 战术层：执行具体动作
            ExecuteTactics();
        }

        /// <summary>
        /// 【智能攻城坑位分配】为部队找到最近的可用攻击位置，避免扎堆
        /// </summary>
        /// <param name="targetCity">目标城市</param>
        /// <param name="takenPositions">已被其他部队占用的位置（军团级别传入）</param>
        /// <returns>分配的攻击位置，new Point(-1, -1)表示没有合适位置</returns>
        public Point GetSmartSiegePosition(Architecture targetCity, HashSet<Point> takenPositions = null)
        {
            if (targetCity == null || targetCity.ArchitectureArea == null)
            {
                return InvalidPosition;
            }

            // 🔥 修复：移除"提前返回"逻辑，改为在候选集中强制加入当前位置
            // 日期：2026-03-07
            // 原因：提前返回导致当前位置不在候选集中，评分机制失效
            // 解决：让当前位置参与评分，通过 +1000 分确保优先级
            
            bool isDefending = (targetCity.BelongedFaction == this.BelongedFaction);
            var cityTiles = targetCity.ArchitectureArea.Area;
            int myAttackRange = this.OffenceRadius;

            // 1. 收集基础信息（保持原有逻辑）
            // 🔥 性能优化：使用 Span 栈分配，避免堆分配（假设友军数量 < 64）
            Span<Point> friendlyPositionsBuffer = stackalloc Point[64];
            int friendlyCount = 0;
            if (this.BelongedLegion != null)
            {
                foreach (Troop t in this.BelongedLegion.Troops)
                {
                    if (t != this && !t.Destroyed && friendlyCount < 64)
                    {
                        friendlyPositionsBuffer[friendlyCount++] = t.Position;
                    }
                }
            }
            var friendlyPositions = friendlyPositionsBuffer[..friendlyCount];

            // 2. 生成候选位置集合（保持原有逻辑）
            HashSet<Point> attackSlotsSet = [];
            if (isDefending)
            {
                if (targetCity.ViewArea != null)
                {
                    foreach (Point p in targetCity.ViewArea.Area)
                        if (!cityTiles.Contains(p)) attackSlotsSet.Add(p);
                }
            }
            else
            {
                int searchRange = Math.Max(2, myAttackRange + 1);
                foreach (Point cityTile in cityTiles)
                {
                    for (int dx = -searchRange; dx <= searchRange; dx++)
                    {
                        for (int dy = -searchRange; dy <= searchRange; dy++)
                        {
                            if (dx == 0 && dy == 0) continue;
                            Point adjacent = new Point(cityTile.X + dx, cityTile.Y + dy);
                            if (!cityTiles.Contains(adjacent)) attackSlotsSet.Add(adjacent);
                        }
                    }
                }
            }

            bool isRanged = myAttackRange >= 2;
            int speed = this.Movability;
            Point committedSiegeDestination = IsValidDestination(this.RealDestination) &&
                                             this.RealDestination != this.Position
                ? this.RealDestination
                : InvalidPosition;
            SmartSiegeHysteresisConfig smartSiegeHysteresis =
                AITacticalConfigManager.Config.TacticalPositioning.SmartSiegeHysteresis;
            TroopPathFinder smartSiegePathFinder = this.pathFinder
                ?? throw new InvalidOperationException($"状态损坏：部队 {this.DisplayName}(ID:{this.ID}) 在 SmartSiege 选位时 pathFinder 为 null。");

            // 3. 评分并收集所有候选点
            // 🔥 性能优化：预分配容量，避免动态扩容
            List<(Point Slot, int Score)> candidates = new(attackSlotsSet.Count);

            foreach (Point slot in attackSlotsSet)
            {
                // --- 基础过滤 (保持原有逻辑) ---
                if (Session.Current.Scenario.PositionOutOfRange(slot)) continue;
                
                int possibleMove = this.GetPossibleMoveByPosition(slot, this.Army.Kind);
                bool blockedByHostileOccupier = false;
                bool blockedByTerrain = false;
                if (possibleMove >= 0xdac)
                {
                    Troop debugOccupier = Session.Current.Scenario.GetTroopByPosition(slot);
                    if ((((this.BelongedFaction == null) && this.ViewArea.HasPoint(slot)) ||
                         ((this.BelongedFaction != null) && this.BelongedFaction.IsPositionKnown(slot))) &&
                        debugOccupier != null &&
                        !debugOccupier.IsFriendly(this.BelongedFaction))
                    {
                        blockedByHostileOccupier = true;
                    }
                    else
                    {
                        blockedByTerrain = !IsTerrainPassableForYield(slot, this.Army.Kind);
                    }
                }

                // 🔥 关键诊断：添加详细日志，找出为什么所有候选坑位被过滤
                // 日期：2026-03-20
                #if DEBUG
                // 🔥 ANTI-BAND-AID：移除防御性空检查，Fail Fast
                // 日期：2026-03-20
                // 原因：如果 Army 或 Kind 为 null，说明数据损坏，应该立即失败
                // 场景：SmartSiege 是战略规划阶段，部队必须有有效的兵种
                if (this.Army == null)
                {
                    throw new InvalidOperationException($"数据损坏：部队 {this.DisplayName}(ID:{this.ID}) 的 Army 为 null");
                }
                if (this.Army.Kind == null)
                {
                    throw new InvalidOperationException($"数据损坏：部队 {this.DisplayName}(ID:{this.ID}) 的 Army.Kind 为 null");
                }

                if (blockedByHostileOccupier || blockedByTerrain)
                {
                    Troop debugOccupier = Session.Current.Scenario.GetTroopByPosition(slot);
                    System.Diagnostics.Debug.WriteLine($"[SmartSiege] {this.DisplayName} 候选坑位 {slot} 被过滤:");
                    System.Diagnostics.Debug.WriteLine($"   GetPossibleMoveByPosition 返回: {possibleMove:X} (>= 0xdac)");
                    System.Diagnostics.Debug.WriteLine($"   Movability: {this.Movability}");

                    if (blockedByHostileOccupier)
                    {
                        System.Diagnostics.Debug.WriteLine($"   原因: 敌军占据 ({debugOccupier.DisplayName})");
                    }
                    else
                    {
                        System.Diagnostics.Debug.WriteLine("   原因: 地形或建筑不可通行");
                    }
                }
                #endif
                
                // 围城选位允许跨回合目标，只过滤真正不可通行或被敌军占据的位置。
                if (blockedByHostileOccupier || blockedByTerrain) continue;
                
                // 🔥 关键修复：如果是当前位置，不要被 takenPositions 过滤
                if (slot != this.Position && takenPositions != null && takenPositions.Contains(slot)) continue;

                Troop occupier = Session.Current.Scenario.GetTroopByPosition(slot);
                if (occupier != null && occupier != this && occupier.BelongedFaction == this.BelongedFaction) continue;

                // --- 射程检查 ---
                int distToCity = int.MaxValue;
                foreach (Point cityTile in cityTiles)
                {
                    int dx = Math.Abs(slot.X - cityTile.X);
                    int dy = Math.Abs(slot.Y - cityTile.Y);
                    int d = this.ObliqueOffence ? Math.Max(dx, dy) : dx + dy;
                    if (d < distToCity) distToCity = d;
                }
                if (distToCity > myAttackRange)
                {
                    #if DEBUG
                    System.Diagnostics.Debug.WriteLine($"[SmartSiege] {this.DisplayName} 候选坑位 {slot} 被过滤:");
                    System.Diagnostics.Debug.WriteLine($"   原因: 超出攻击范围 (距离:{distToCity}, 范围:{myAttackRange}, 斜向:{this.ObliqueOffence})");
                    #endif
                    continue;
                }

                // --- 评分计算 (保持原有逻辑) ---
                int distToTarget = 0;
                if (slot != this.Position)
                {
                    List<Point> simulatedPath = smartSiegePathFinder.GetFirstTierSimulatePath(this.Position, slot, this.Army.Kind);
                    if (simulatedPath == null || simulatedPath.Count == 0)
                    {
                        #if DEBUG
                        System.Diagnostics.Debug.WriteLine($"[SmartSiege] {this.DisplayName} 候选坑位 {slot} 被过滤:");
                        System.Diagnostics.Debug.WriteLine("   原因: 模拟寻路失败");
                        #endif
                        continue;
                    }
                    distToTarget = simulatedPath.Count;
                }
                int minDistToFriendly = 999;
                // 🔥 性能优化：使用 for 循环遍历 Span
                for (int i = 0; i < friendlyPositions.Length; i++)
                {
                    Point friendlyPos = friendlyPositions[i];
                    int dist = Math.Abs(slot.X - friendlyPos.X) + Math.Abs(slot.Y - friendlyPos.Y);
                    if (dist < minDistToFriendly) minDistToFriendly = dist;
                }

                int score = 0;
                score += minDistToFriendly * 10;

                if (isRanged)
                {
                    if (distToCity >= 2) score += 100 + (myAttackRange >= 3 && distToCity >= 3 ? 50 : 0);
                    else if (distToCity == 1) score -= 80;
                    score += minDistToFriendly * 15;
                }
                else
                {
                    if (distToCity == 1) score += 150;
                    else if (distToCity == 2) score += 30;
                    else score -= 50;
                    if (minDistToFriendly <= 2) score += 20;
                }

                // 机动性修正
                if (speed >= 130) score -= Math.Min(distToTarget / 2, 10);
                else if (speed >= 100) score -= Math.Min(distToTarget, 15);
                else score -= Math.Min(distToTarget * 2, 30);

                if (distToTarget <= speed / 20) score += 10;
                
                // 🔥 关键修复：如果是当前位置，大幅提升评分（优先保持不动）
                if (slot == this.Position) score += SmartSiegeCurrentPositionScoreBonus;
                if (slot == committedSiegeDestination) score += smartSiegeHysteresis.CommittedDestinationScoreBonus;
                
                if (score < -10) score = -10;

                // 加入候选列表
                candidates.Add((slot, score));
            }

            // 4. 【关键修复】选择最高分候选点
            // 日期：2026-03-08
            
#if DEBUG
            System.Diagnostics.Debug.WriteLine($"[SmartSiege] {this.DisplayName} 生成了 {candidates.Count} 个候选坑位");
#endif
            
            if (candidates.Count == 0)
            {
#if DEBUG
                System.Diagnostics.Debug.WriteLine($"[SmartSiege] ✗ {this.DisplayName} 无候选坑位（所有位置被过滤）");
                System.Diagnostics.Debug.WriteLine($"[SmartSiege]   - 攻击范围: {myAttackRange}, 位置: {this.Position}, 目标城市: {targetCity.Name}");
                System.Diagnostics.Debug.WriteLine($"[SmartSiege]   - takenPositions 数量: {takenPositions?.Count ?? 0}");
#endif
                return InvalidPosition;
            }
            
            // 🔥 性能优化：手动查找最高分（避免 LINQ）
            // 日期：2026-03-08
            // 理由：虽然是 AI 决策阶段（非每帧），但仍属于游戏逻辑，应避免 LINQ
            // 上下文：AI 决策逻辑，性能优先
            (Point Slot, int Score) bestCandidate = candidates[0];
            (Point Slot, int Score) committedCandidate = default;
            bool hasCommittedCandidate = false;
            if (candidates[0].Slot == committedSiegeDestination)
            {
                committedCandidate = candidates[0];
                hasCommittedCandidate = true;
            }

            for (int i = 1; i < candidates.Count; i++)
            {
                if (candidates[i].Slot == committedSiegeDestination)
                {
                    committedCandidate = candidates[i];
                    hasCommittedCandidate = true;
                }

                if (candidates[i].Score > bestCandidate.Score)
                {
                    bestCandidate = candidates[i];
                }
            }

            if (hasCommittedCandidate && bestCandidate.Slot != committedCandidate.Slot)
            {
                int thresholdPercent = smartSiegeHysteresis.ReassignThresholdPercent;
                int minimumScoreGain = smartSiegeHysteresis.MinimumScoreGain;
                int distanceToCommitted = Math.Max(
                    Math.Abs(this.Position.X - committedCandidate.Slot.X),
                    Math.Abs(this.Position.Y - committedCandidate.Slot.Y));
                if (distanceToCommitted <= smartSiegeHysteresis.NearDestinationDistance)
                {
                    thresholdPercent += smartSiegeHysteresis.NearDestinationThresholdPercentBonus;
                    minimumScoreGain += smartSiegeHysteresis.NearDestinationMinimumScoreGainBonus;
                }

                int relaxStacks = Math.Min(smartSiegeHysteresis.MaxStuckRelaxStacks, Math.Max(0, this.stuckedFor));
                if (relaxStacks > 0)
                {
                    thresholdPercent = Math.Max(0, thresholdPercent - relaxStacks * smartSiegeHysteresis.StuckRelaxPerStackPercent);
                    minimumScoreGain = Math.Max(0, minimumScoreGain - relaxStacks * smartSiegeHysteresis.StuckRelaxPerStackScore);
                }

                int committedReferenceScore = committedCandidate.Score - smartSiegeHysteresis.CommittedDestinationScoreBonus;
                int requiredGain = Math.Max(
                    minimumScoreGain,
                    (Math.Max(0, committedReferenceScore) * thresholdPercent + 99) / 100);

                if (bestCandidate.Score < committedReferenceScore + requiredGain)
                {
#if DEBUG
                    System.Diagnostics.Debug.WriteLine(
                        $"[SmartSiege] {this.DisplayName} hysteresis keeps committed position {committedCandidate.Slot}, " +
                        $"committedScore={committedReferenceScore}, bestScore={bestCandidate.Score}, " +
                        $"requiredGain={requiredGain}, thresholdPercent={thresholdPercent}, minimumScoreGain={minimumScoreGain}");
#endif
                    bestCandidate = committedCandidate;
                }
            }

            // 🔥 关键修复：移除寻路验证，直接返回最高分候选点
            // 日期：2026-03-08
            // 原因：pathFinder.GetFirstTierPath() 会修改 this._firstTierPath，污染后续的异步寻路结果
            //       导致部队寻路到错误的位置（使用了被污染的路径数据）
            // 场景：SmartSiege 验证可达性 → 修改 _firstTierPath → 异步寻路完成 → 使用被污染的路径
            // 解决：评分机制已经考虑了距离、地形等因素，无需额外验证
            //       即使选择的点暂时不可达，UpdateMovementLogic 会自动处理（寻路失败 → 增加 stuckedFor → 触发熔断）
            
#if DEBUG
            System.Diagnostics.Debug.WriteLine($"[SmartSiege] ✓ {this.DisplayName} 选中最佳位置:{bestCandidate.Slot} 评分:{bestCandidate.Score}");
            if (bestCandidate.Slot == this.Position)
            {
                System.Diagnostics.Debug.WriteLine($"[SmartSiege]   → 已在目标位置，无需移动");
            }
#endif
            
            return bestCandidate.Slot;
        }

        private bool ShouldResetStuckCounterForDestinationChange(Point oldDestination, Point newDestination)
        {
            if (oldDestination == newDestination || !IsValidDestination(newDestination) || newDestination == Point.Zero)
            {
                return false;
            }

            Architecture currentSiegeTarget = this.TargetArchitecture ?? this.WillArchitecture;
            if (currentSiegeTarget != null &&
                currentSiegeTarget.BelongedFaction != this.BelongedFaction &&
                this.TryGetCommittedSmartSiegePosition(currentSiegeTarget, out Point committedSiegePosition) &&
                newDestination == committedSiegePosition &&
                !IsSmartSiegeSlotForTargetArchitecture(oldDestination, currentSiegeTarget))
            {
#if DEBUG
                if (this.stuckedFor > 0)
                {
                    System.Diagnostics.Debug.WriteLine(
                        $"[SmartSiege] {this.DisplayName} preserves stuck counter when restoring committed siege slot {oldDestination} -> {newDestination}, stuckedFor={this.stuckedFor}");
                }
#endif
                return false;
            }

            if (!IsSameSmartSiegeRetarget(oldDestination, newDestination))
            {
                return true;
            }

#if DEBUG
            Architecture siegeTarget = this.TargetArchitecture ?? this.WillArchitecture;
            System.Diagnostics.Debug.Assert(
                siegeTarget != null &&
                IsSmartSiegeSlotForTargetArchitecture(oldDestination, siegeTarget) &&
                IsSmartSiegeSlotForTargetArchitecture(newDestination, siegeTarget),
                $"[SmartSiege] Retarget must stay in the same architecture slot set: troop={this.DisplayName}, old={oldDestination}, new={newDestination}");
            if (this.stuckedFor > 0)
            {
                System.Diagnostics.Debug.WriteLine(
                    $"[SmartSiege] {this.DisplayName} preserves stuck counter for siege retarget {oldDestination} -> {newDestination}, stuckedFor={this.stuckedFor}");
            }
#endif
            return false;
        }

        private bool IsSameSmartSiegeRetarget(Point oldDestination, Point newDestination)
        {
            if (!IsSmartSiegeSlotForCurrentTarget(oldDestination) || !IsSmartSiegeSlotForCurrentTarget(newDestination))
            {
                return false;
            }

            return oldDestination != newDestination;
        }

        private bool IsSmartSiegeSlotForCurrentTarget(Point destination)
        {
            Architecture currentTarget = this.TargetArchitecture ?? this.WillArchitecture;
            return IsSmartSiegeSlotForTargetArchitecture(destination, currentTarget);
        }

        internal bool IsSmartSiegeSlotForTargetArchitecture(Point destination, Architecture siegeTarget)
        {
            if (siegeTarget == null || siegeTarget.ArchitectureArea == null || siegeTarget.BelongedFaction == this.BelongedFaction)
            {
                return false;
            }

            if (!IsValidDestination(destination) || siegeTarget.ArchitectureArea.HasPoint(destination))
            {
                return false;
            }

            int attackRange = this.OffenceRadius;
            if (attackRange <= 0)
            {
                return false;
            }

            foreach (Point cityTile in siegeTarget.ArchitectureArea.Area)
            {
                int dx = Math.Abs(destination.X - cityTile.X);
                int dy = Math.Abs(destination.Y - cityTile.Y);
                int distanceToCity = this.ObliqueOffence ? Math.Max(dx, dy) : dx + dy;
                if (distanceToCity <= attackRange)
                {
                    return true;
                }
            }

            return false;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private void ClearCommittedSmartSiegePosition()
        {
            this._committedSmartSiegePosition = InvalidPosition;
            this._committedSmartSiegeArchitectureId = -1;
        }

        private void RememberCommittedSmartSiegePosition(Architecture targetArchitecture, Point siegePosition)
        {
            if (!IsSmartSiegeSlotForTargetArchitecture(siegePosition, targetArchitecture))
            {
                return;
            }

            this._committedSmartSiegePosition = siegePosition;
            this._committedSmartSiegeArchitectureId = targetArchitecture.ID;
        }

        private bool TryGetCommittedSmartSiegePosition(Architecture targetArchitecture, out Point committedSiegePosition)
        {
            committedSiegePosition = InvalidPosition;
            if (targetArchitecture == null ||
                this._committedSmartSiegeArchitectureId != targetArchitecture.ID ||
                !IsSmartSiegeSlotForTargetArchitecture(this._committedSmartSiegePosition, targetArchitecture))
            {
                return false;
            }

            committedSiegePosition = this._committedSmartSiegePosition;
            return true;
        }

        private void SyncAttackArchitectureExecutionTarget(Architecture targetArchitecture, Point siegePosition)
        {
            this.RememberCommittedSmartSiegePosition(targetArchitecture, siegePosition);
            this.ClearExecutionTarget();
            this.BeginExecutionTarget(
                ExecutionActionKind.AttackArchitecture,
                siegePosition,
                targetArchitecture.ID);
        }

        private bool TrySyncResolvedAttackArchitectureDestination(Point resolvedDestination)
        {
            Architecture targetArchitecture = this.GetExecutionTargetArchitecture() ?? this.TargetArchitecture ?? this.WillArchitecture;
            if (targetArchitecture == null || targetArchitecture.BelongedFaction == this.BelongedFaction)
            {
                return false;
            }

            if (resolvedDestination == this.Position)
            {
                if (!this.CanAttack(targetArchitecture))
                {
                    return false;
                }

                this.SyncAttackArchitectureExecutionTarget(targetArchitecture, resolvedDestination);
                return true;
            }

            if (!IsSmartSiegeSlotForTargetArchitecture(resolvedDestination, targetArchitecture))
            {
                return false;
            }

            this.SyncAttackArchitectureExecutionTarget(targetArchitecture, resolvedDestination);
            return true;
        }

        internal bool TryReserveCommittedSmartSiegePosition(Architecture targetCity, HashSet<Point> takenPositions)
        {
            if (targetCity == null || targetCity != this.WillArchitecture)
            {
                return false;
            }

            Point committedSiegeDestination = this.RealDestination;
            if (!this.TryGetCommittedSmartSiegePosition(targetCity, out committedSiegeDestination))
            {
                committedSiegeDestination = this.RealDestination;
            }

            if (!IsSmartSiegeSlotForTargetArchitecture(committedSiegeDestination, targetCity) ||
                this.stuckedFor >= SmartSiegeCommitReleaseStuckThreshold ||
                takenPositions.Contains(committedSiegeDestination))
            {
                return false;
            }

            Troop occupier = Session.Current.Scenario.GetTroopByPosition(committedSiegeDestination);
            if (occupier != null && occupier != this)
            {
                return false;
            }

            takenPositions.Add(committedSiegeDestination);
            return true;
        }

        /// <summary>
        /// 【智能攻城】应用分配的攻击位置，设置寻路目标
        /// </summary>
        public bool ApplySmartSiegePosition(Point siegePosition)
        {
            if (siegePosition == new Point(-1, -1)) return false;
            if (this.IsExecutionTargetLockedForCurrentTick() &&
                this.HasExecutionTargetFor(ExecutionActionKind.AttackArchitecture) &&
                this.GetExecutionTargetPosition() != siegePosition)
            {
                return false;
            }

            if (siegePosition == this.Position)
            {
                Architecture smartSiegeTarget = this.TargetArchitecture ?? this.WillArchitecture;
                if (smartSiegeTarget != null && smartSiegeTarget.BelongedFaction != this.BelongedFaction)
                {
                    this.SyncAttackArchitectureExecutionTarget(smartSiegeTarget, siegePosition);
                }
                else
                {
                    this.RealDestination = this.Position;
                }

                this.Destination = this.Position;
                this.HasPath = false;
                this.Action = TroopAction.Stop;
                if (this._cachedPath.Count > 0) this._cachedPath.Clear();
                if (this._firstTierPath != null && this._firstTierPath.Count > 0)
                {
                    this.ClearFirstTierPath();
                    this.FirstIndex = 0;
                }
                return true;
            }

            // ★★★ 修复：如果移动力已耗尽，直接跳过，不设置目标 ★★★
            // 日期：2026-03-04
            // 原因：设置目标但不寻路会导致 CheckMovementCompleted 检测到"未到达目标"
            //       触发重新启动任务，但因为移动力为0，ExecuteMoveTurnAsync 立即失败
            // 解决：移动力为0时，完全跳过本次分配，保持原目标，等待下回合恢复移动力
            if (this.MovabilityLeft <= 0)
            {
                // 🔥 移除冗余日志：这是正常行为，不需要每次都输出
                // 日期：2026-03-21
                // 原因：AILegions 在战略阶段被调用，此时部队已移动完毕，MovabilityLeft = 0
                //       这是预期行为，不是错误，不需要输出日志
                return false; // 返回false表示当前无法分配
            }

            Architecture currentSiegeTarget = this.TargetArchitecture ?? this.WillArchitecture;
            if (currentSiegeTarget != null && currentSiegeTarget.BelongedFaction != this.BelongedFaction)
            {
                this.SyncAttackArchitectureExecutionTarget(currentSiegeTarget, siegePosition);
            }
            else
            {
                this.RealDestination = siegePosition;
            }
            MarkLegacyMoveInvalidated(LegacyMoveInvalidationTargetChanged);
            MarkLegacyMoveInvalidated(LegacyMoveInvalidationSiegeSlotChanged);
            
            // 🔥 关键修复：移除立即寻路，改为设置状态让 UpdateMovementLogic 处理
            // 日期：2026-03-08
            // 原因：pathFinder.GetFirstTierPath() 会修改 this._firstTierPath，污染后续的异步寻路结果
            //       导致部队寻路到错误的位置（使用了被污染的路径数据）
            // 场景：ApplySmartSiegePosition 立即寻路 → 修改 _firstTierPath → 异步寻路完成 → 使用被污染的路径
            // 解决：只设置 RealDestination 和状态，让 UpdateMovementLogic 统一处理寻路
            //       这样可以避免路径数据污染，并且使用异步寻路机制
            
            // 清空旧路径，强制重新寻路
            if (this._cachedPath.Count > 0) this._cachedPath.Clear();
            if (this._firstTierPath != null && this._firstTierPath.Count > 0)
            {
                this.ClearFirstTierPath();
                this.FirstIndex = 0;
            }
            
            // 设置状态，让 UpdateMovementLogic 在下一帧处理寻路
            this.HasPath = false; // 标记为无路径，触发寻路
            this.CurrentAIState = TroopAIState.Marching;
            this.Action = TroopAction.Move;
            
            #if DEBUG
            System.Diagnostics.Debug.WriteLine($"[SmartSiege] {this.DisplayName} 设置目标到 {siegePosition}，状态为 Marching, MovLeft={this.MovabilityLeft}");
            #endif

            return true; // 总是返回 true，因为我们已经设置了目标和状态
        }

        /// <summary>
        /// 【智能防卡】检查下一步是否被友军或目标建筑阻挡
        /// </summary>
        private void ResetMovePathForResolvedDestination(Point resolvedDestination)
        {
            bool preserveFrozenExecutionTarget =
                this.IsExecutionTargetLockedForCurrentTick() &&
                resolvedDestination == this.Position &&
                this.HasReachedEffectiveLegacyDestination();
            bool attackArchitectureContext =
                this.HasExecutionTargetFor(ExecutionActionKind.AttackArchitecture) ||
                this.HasArchitectureAttackCommandContext();
            if (preserveFrozenExecutionTarget)
            {
                this.destination = resolvedDestination;
            }
            else if (!this.TrySyncResolvedAttackArchitectureDestination(resolvedDestination) &&
                     !attackArchitectureContext)
            {
                this.ForceSetRealDestination(resolvedDestination);
            }

            this.Destination = resolvedDestination;
            this._friendlyBlockWaitUntilTurn = -1;
            MarkLegacyMoveInvalidated(LegacyMoveInvalidationTargetChanged);
            this.ClearCurrentPath();

            if (this._cachedPath.Count > 0) this._cachedPath.Clear();
            if (this._firstTierPath != null && this._firstTierPath.Count > 0)
            {
                this.ClearFirstTierPath();
                this.FirstIndex = 0;
            }

            this.HasPath = false;
            this.CurrentAIState = TroopAIState.Marching;
        }

        private void ResetLegacyMoveTaskDestination(Point resolvedDestination)
        {
            TroopAIState currentState = this.CurrentAIState;
            ResetMovePathForResolvedDestination(resolvedDestination);
            this.CurrentAIState = currentState;
        }

        private bool TryResolveOccupiedSiegeDestination()
        {
            if (this.WillArchitecture == null || this.WillArchitecture.BelongedFaction == this.BelongedFaction) return false;
            if (!IsValidDestination(this.RealDestination) || this.RealDestination == this.Position) return false;

            Troop occupier = Session.Current.Scenario.GetTroopByPosition(this.RealDestination);
            if (occupier == null || occupier == this) return false;

            if (occupier.IsFriendly(this.BelongedFaction))
            {
                HashSet<Point> takenPositions = [occupier.Position];
                Point reassignedSiegePosition = this.GetSmartSiegePosition(this.WillArchitecture, takenPositions);
                if (!IsValidDestination(reassignedSiegePosition) || reassignedSiegePosition == this.RealDestination) return false;

                ResetMovePathForResolvedDestination(reassignedSiegePosition);
#if DEBUG
                System.Diagnostics.Debug.WriteLine($"[ExecuteMoveTurnAsync] {this.DisplayName} 攻城位被友军 {occupier.DisplayName} 占用，改派新站位 {reassignedSiegePosition}");
#endif
                return true;
            }

            if (this.CanAttack(occupier))
            {
                this.TargetTroop = occupier;
                this.RealDestination = this.Position;
                this.Destination = this.Position;
                if (this._cachedPath.Count > 0) this._cachedPath.Clear();
                if (this._firstTierPath != null && this._firstTierPath.Count > 0)
                {
                    this.ClearFirstTierPath();
                    this.FirstIndex = 0;
                }
                this.HasPath = false;
                this.Action = TroopAction.Stop;
#if DEBUG
                System.Diagnostics.Debug.WriteLine($"[ExecuteMoveTurnAsync] {this.DisplayName} 攻城位被敌军 {occupier.DisplayName} 抢先占据，改为就地交战");
#endif
                return true;
            }

            Point occupiedAttackPosition = this.OffenceRadius > 1
                ? this.GetOptimalAttackPosition(occupier)
                : this.FindNearestPassableToTarget(occupier.Position, 1);
            if (IsValidDestination(occupiedAttackPosition)
                && occupiedAttackPosition != occupier.Position
                && occupiedAttackPosition != this.RealDestination)
            {
                this.TargetTroop = occupier;
                ResetMovePathForResolvedDestination(occupiedAttackPosition);
#if DEBUG
                System.Diagnostics.Debug.WriteLine($"[ExecuteMoveTurnAsync] {this.DisplayName} 攻城位被敌军 {occupier.DisplayName} 抢先占据，改为逼近敌军位置 {occupiedAttackPosition}");
#endif
                return true;
            }

            HashSet<Point> hostileTakenPositions = [occupier.Position];
            Point fallbackSiegePosition = this.GetSmartSiegePosition(this.WillArchitecture, hostileTakenPositions);
            if (!IsValidDestination(fallbackSiegePosition) || fallbackSiegePosition == this.RealDestination) return false;

            ResetMovePathForResolvedDestination(fallbackSiegePosition);
#if DEBUG
            System.Diagnostics.Debug.WriteLine($"[ExecuteMoveTurnAsync] {this.DisplayName} 攻城位被敌军 {occupier.DisplayName} 占据，改派备用站位 {fallbackSiegePosition}");
#endif
            return true;
        }

        private bool IsBlockedByFriendlyOrTarget(Point nextPos)
        {
            if (nextPos == new Point(-1, -1) || nextPos == this.Position) return false;

            // 1. 检查是否被部队阻挡
            Troop blockingTroop = Session.Current.Scenario.GetTroopByPosition(nextPos);
            if (blockingTroop != null && blockingTroop != this)
            {
                // 如果是己方部队，视为排队
                if (this.BelongedFaction != null && blockingTroop.BelongedFaction == this.BelongedFaction)
                {
                    return true;
                }
            }

            // 2. 检查是否被建筑阻挡
            Architecture blockingArch = Session.Current.Scenario.GetArchitectureByPosition(nextPos);
            if (blockingArch != null)
            {
                // 如果障碍物正是我的目标（攻城/回城）
                if (blockingArch == this.WillArchitecture || blockingArch == this.TargetArchitecture)
                {
                    return true;
                }
                // 如果是己方建筑（借道）
                if (this.BelongedFaction != null && blockingArch.BelongedFaction == this.BelongedFaction)
                {
                    return true;
                }
            }
            return false;
        }

        /// <summary>
        /// 【智能防卡】尝试获取寻路的下一步位置
        /// </summary>
        private Point GetNextPathPointForStuckCheck()
        {
            // 新系统：从 _cachedPath 获取路径信息
            if (this._cachedPath != null && this._cachedPath.Count > 0)
            {
                foreach (Point p in this._cachedPath)
                {
                    if (p != this.Position) return p;
                }
            }
            
            // 如果新系统没有路径数据，返回 (-1, -1) 避免误判
            // 这可能是因为正在异步计算路径中
            return new Point(-1, -1);
        }

        private bool AIResetDestination()
        {
            // [新增] 第一步：异步保护锁
            // 异步保护锁：如果正在寻路中，直接退出，完全信任新系统的回调
            // 避免老代码误判
            if (_isPathfinding)
            {
                return true;
            }

            // ... 原有的 stuckPosition 和防卡逻辑保持不变 ...
            if (this.Position == stuckPosition)
            {
                // 如果正在寻路中，不要触发老的防卡逻辑
                // 避免在新系统计算路径的微小间隙中误判为卡死
                if (_isPathfinding)
                {
                    stuckedFor = 0; // 正在计算中，视为正常等待
                }
                else
                {
                    // === [保留核心逻辑] 智能防卡判定 ===

                    bool isQueuing = false;
                    Point nextStep = GetNextPathPointForStuckCheck();

                    // 判定是“排队”还是“真卡死”
                    // 只有明确知道下一步要去哪，且被友军/目标阻挡时，才算排队
                    if (nextStep != new Point(-1, -1) && IsBlockedByFriendlyOrTarget(nextStep))
                    {
                        isQueuing = true;
                    }

                    if (isQueuing)
                    {
                        // 处于“排队”状态，重置计数器，耐心等待
                        stuckedFor = 0;
                        queuedFor++;

                        // 容忍3次计算周期的拥堵，超过则强制打断排队
                        if (queuedFor >= 3)
                        {
#if DEBUG
                            System.Diagnostics.Debug.WriteLine($"[拥挤分流] {this.DisplayName} 排队过久，强制重新寻路");
#endif
                            this.HasPath = false;
                            this.ClearFirstTierPath();
                            queuedFor = 0;
                        }
                    }
                    else
                    {
                        // 前方是地形、敌人或未知障碍 -> 累积卡死计数
                        queuedFor = 0;
                        stuckedFor++;

                        // [优化] 如果长期卡住且没有路径，尝试强制触发寻路刷新
                        if (nextStep == new Point(-1, -1) && this.WillArchitecture != null)
                        {
                            this.HasPath = false; // 强制标记为无路径，促使下一帧重新寻路
                        }
                    }

                    // === [保留核心逻辑] 熔断机制 ===

                    // 动态阈值：如果有明确目标但暂时无路，多给点时间
                    int stuckThreshold = (nextStep == new Point(-1, -1) && this.WillArchitecture != null) ? 15 : 5;

                    if (stuckedFor >= stuckThreshold)
                    {
                        System.Diagnostics.Debug.WriteLine($"[智能防卡] {this.DisplayName} 判定卡死 (计数:{stuckedFor}) -> 触发熔断处理");

                        if (stuckedFor >= stuckThreshold + 3)
                        {
                            // 严重卡死：随机移动尝试脱困
                            this.RealDestination = new Point(stuckPosition.X + GameObject.Random(5) - 2, stuckPosition.Y + GameObject.Random(5) - 2);
                            this.AttackTargetKind = TroopAttackTargetKind.无反默认;
                            return false;
                        }
                        else
                        {
                            // 一般卡死：触发撤退
                            this.GoBack();
                            this.AttackTargetKind = TroopAttackTargetKind.无反默认;
                            return false;
                        }
                    }
                }
            }
            else
            {
                // 位置发生了变化，重置状态
                stuckPosition = this.Position;
                stuckedFor = 0;
            }

            // ... 后续原有逻辑在此继续执行 ...

            return true;
        }

        public bool AmbushAvail(int id)
        {
            if (this.Status != TroopStatus.埋伏)
            {
                if (this.ProhibitAllAction || this.ProhibitStratagem)
                {
                    return false;
                }
                Stratagem stratagem = this.Stratagems.GetStratagem(id);
                if (stratagem != null)
                {
                    if (stratagem.Combativity <= (this.Combativity + this.DecrementOfStratagemCombativityConsuming))
                    {
                        switch (Session.Current.Scenario.GetTerrainKindByPosition(this.Position))
                        {
                            case TerrainKind.森林:
                            case TerrainKind.山地:
                                {
                                    if (Session.Current.Scenario.GetArchitectureByPosition(this.Position) != null)
                                    {
                                        return false;
                                    }
                                    // 🔥 使用 EffectiveViewRadius 而不是 ViewRadius
                                    // 日期：2026-03-16
                                    GameArea area = GameArea.GetViewArea(this.Position, (3 > this.EffectiveViewRadius) ? this.EffectiveViewRadius : 3, false, null);
                                    foreach (Point point in area.Area)
                                    {
                                        if (((this.BelongedFaction == null) && this.ViewArea.HasPoint(point)) || ((this.BelongedFaction != null) && !this.BelongedFaction.IsPositionKnown(point)))
                                        {
                                            continue;
                                        }
                                        Troop troopByPosition = Session.Current.Scenario.GetTroopByPosition(point);
                                        if ((troopByPosition != null) && !(this.IsFriendly(troopByPosition.BelongedFaction) || (troopByPosition.Status == TroopStatus.埋伏)))
                                        {
                                            return false;
                                        }
                                        Architecture architectureByPosition = Session.Current.Scenario.GetArchitectureByPosition(point);
                                        if (((architectureByPosition != null) && (architectureByPosition.BelongedFaction != null)) && !this.IsFriendly(architectureByPosition.BelongedFaction))
                                        {
                                            return false;
                                        }
                                    }
                                    return true;
                                }
                        }
                    }
                    return false;
                }
            }
            return false;
        }

        public void AmbushDetected(Troop troop)
        {
            troop.Status = TroopStatus.一般;
            troop.OperationDone = true;
            troop.MovabilityLeft = -1;
            if (this.OnDiscoverAmbush != null)
            {
                if (this != troop)
                {
                    this.OnDiscoverAmbush(this, troop);
                }
                else
                {
                    this.OnDiscoverAmbush(null, troop);
                }
            }
            ExtensionInterface.call("AmbushDetected", new Object[] { Session.Current.Scenario, this, troop });
        }

        private void ApplyAreaInfluences(Point p)
        {
            // 🔥 修复 NullReferenceException：添加安全检查
            if (Session.Current?.Scenario?.MapTileData == null)
            {
                System.Diagnostics.Debug.WriteLine("[ApplyAreaInfluences] MapTileData 为 null");
                return;
            }
            
            if (Session.Current.Scenario.PositionOutOfRange(p))
            {
                System.Diagnostics.Debug.WriteLine($"[ApplyAreaInfluences] 位置越界: ({p.X}, {p.Y})");
                return;
            }
            
            try
            {
                if (Session.Current.Scenario.MapTileData[p.X, p.Y].AreaInfluenceList != null)
                {
                    foreach (AreaInfluenceData data in Session.Current.Scenario.MapTileData[p.X, p.Y].AreaInfluenceList)
                    {
                        data.ApplyAreaInfluence(this);
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ApplyAreaInfluences] 访问异常: {ex.Message}");
            }
        }

        public void ApplyCurrentStunt()
        {
            if (this.CurrentStunt != null)
            {
                #if DEBUG
                var stackTrace = new System.Diagnostics.StackTrace(1, true);
                var callerFrame = stackTrace.GetFrame(0);
                var callerInfo = callerFrame?.ToString()?.Trim() ?? "Unknown";
                System.Diagnostics.Debug.WriteLine($"[ApplyCurrentStunt] 部队 {this.ID} ({this.Name}) 触发特技: {this.CurrentStunt.Name}");
                System.Diagnostics.Debug.WriteLine($"[ApplyCurrentStunt] 调用者: {callerInfo}");
                System.Diagnostics.Debug.WriteLine($"[ApplyCurrentStunt] 是否玩家势力: {this.BelongedFaction != null && Session.Current.Scenario.IsPlayer(this.BelongedFaction)}");
                #endif
                
                this.CurrentStunt.Apply(this);
                this.StuntDayLeft += this.IncrementOfStuntDay;
                if (this.OnApplyStunt != null)
                {
                    this.OnApplyStunt(this, this.CurrentStunt);
                }
            }
        }
