        public void InitializeInfluences()
        {
            if (this.Army != null)
            {
                this.Army.ApplyFollowedLeader(this);
                foreach (Influence influence in this.Army.Kind.Influences.Influences.Values)
                {
                    influence.ApplyInfluence(this, Applier.MilitaryKind, 0);
                }
            }
            this.ApplyFactionInfluences();
            this.ApplyEventEffectInfluences();
            this.ApplyStuntInfluences();
        }

        /// <summary>
        /// 清理瞬时执行态（动作/动画忙态）
        /// 日期：2026-03-24
        /// 用途：在执行阶段结束时统一清理临时动作状态，防止泄漏到战略阶段
        /// 
        /// 清理范围：
        /// - Action 中的瞬时动作（Move/Attack/Cast/BeAttacked/BeCasted）
        /// - ShowNumber（伤害数字显示）
        /// - PreAction（前置动作）
        /// - WaitForDeepChaosFrameCount（深度混乱等待帧）
        /// 
        /// 不清理的内容（这些属于结果态/命令态/业务态）：
        /// - OperationDone
        /// - Command
        /// - Quantity
        /// - Destroyed
        /// - TargetTroop/TargetArchitecture
        /// - CurrentStratagem/CurrentCombatMethod
        /// - MovabilityLeft
        /// </summary>
        public void ClearTransientExecutionState(bool clearExecutionTarget = true)
        {
            if (clearExecutionTarget)
            {
                this.ClearExecutionTarget();
            }
            // 只清理瞬时执行态动作，不清理 Stop（Stop 是正常状态）
            if (this.Action == TroopAction.Move ||
                this.Action == TroopAction.Attack ||
                this.Action == TroopAction.Cast ||
                this.Action == TroopAction.BeAttacked ||
                this.Action == TroopAction.BeCasted)
            {
                this.Action = TroopAction.Stop;
            }

            // 清理显示相关的瞬时状态
            this.ShowNumber = false;
            this.PreAction = TroopPreAction.无;
            this.WaitForDeepChaosFrameCount = 0;

            #if DEBUG
            // 仅在清理了非 Stop 动作时输出日志
            if (this.Action != TroopAction.Stop)
            {
                System.Diagnostics.Debug.WriteLine($"[ClearTransientExecutionState] {this.DisplayName} 清理瞬时执行态");
            }
            #endif
        }

        public void InitializeInQueue()
        {
            this.Moved = false;
            this.QueueEnded = false;
            this.WaitOnce = false;
            this.OperationDone = false;
            this.HasToDoCombatAction = false; // 🔥 修复：重置计略/攻击执行标志，允许新回合下达新指令
            this.AttackedTroopList.Clear();
            
            // 🔥 修复：无条件恢复移动力，这是新回合的开始
            // 移除多余的 if (!this.OperationDone) 检查
            this.MovabilityLeft = this.Movability;
            
            // 🔥 根本修复：重置寻路冷却，允许新回合立即寻路
            // 日期：2026-02-27
            // 原因：第一回合结束时 _pathfindingCooldown 有残留值（如 0.098 秒）
            //       第二回合开始时，RequestPathAsync 被冷却阻止，导致部队无法寻路
            // 解决：在回合开始时重置冷却，确保新回合可以立即寻路
            this._pathfindingCooldown = 0;
            this._moveStepCooldown = 0;
            
            // 🔥 根本修复：重置 Action 状态，避免战略阶段显示"被攻"等执行阶段状态
            // 日期：2026-03-24
            // 原因：上一回合执行阶段设置的 Action（如 BeAttacked）没有被清理
            //       导致新回合战略阶段仍然显示"被攻"状态
            // 解决：在回合开始时调用统一清理方法
            this.ClearTransientExecutionState();
            
            #if DEBUG
            if (this.ManualControl)
            {
                System.Diagnostics.Debug.WriteLine($"[InitializeInQueue] {this.DisplayName} 回合开始: MovabilityLeft={this.MovabilityLeft}, HasPath={this.HasPath}, Action={this.Action}, CurrentAIState={this.CurrentAIState}");
            }
            #endif
            
            if (this.ProhibitCombatMethod)
            {
                // 🔥 修复：保护玩家手动选择的战法
                // 日期：2026-03-12
                // 问题：InitializeInQueue 在"进行"阶段开始时清空战法
                //       此时玩家可能已经选择了战法，正在选择目标
                //       清空战法会导致目标选择失败
                // 解决：只清空 AutoCombatMethodID（AI 自动战法），保留 CurrentCombatMethod（玩家手动选择）
                //       玩家手动选择的战法应该在 DoCombatAction 执行后才清空
                this.AutoCombatMethodID = -1;
                // this.CurrentCombatMethod = null;  // ❌ 不清空玩家手动选择的战法
            }
            if (this.ProhibitStratagem)
            {
                // 🔥 注意：ProhibitStratagem 是游戏机制效果（如被技能影响），应该强制清空所有计略
                // 这与 ProhibitCombatMethod 不同，后者只清空 AI 自动战法
                // 日期：2026-03-12
                this.CurrentStratagem = null;
            }
            if (this.ProhibitAllAction)
            {
                this.CurrentCombatMethod = null;
                this.CurrentStratagem = null;
                this.OperationDone = true;
            }
            if ((this.CurrentStunt != null) && (this.StuntDayLeft > 0))
            {
            }
            if (this.AutoCombatMethodID != -1)
            {
                this.CurrentStratagem = null;
                this.CurrentCombatMethod = Session.Current.Scenario.GameCommonData.AllCombatMethods.GetCombatMethod(this.AutoCombatMethodID);
                //this.CurrentCombatMethod.Apply(this);
                //this.RefreshAllData();
            }
            
            // 🔥 修复：移除错误的战法施放逻辑
            // 日期：2026-03-12
            // 问题：InitializeInQueue 在回合开始时就调用 Apply()，导致 CombatMethodApplied = true
            //       当 DoCombatAction 执行时，条件 !CombatMethodApplied 失败，跳过战法分支
            // 根因：战法应该在 DoCombatAction 中施放，而不是在回合初始化时
            // 解决：移除此处的 Apply() 调用，让战法在正确的时机（攻击时）施放
            // if (this.CurrentCombatMethod != null)
            // {
            //     this.CurrentCombatMethod.Apply(this);  // ❌ 错误：过早施放战法
            // }
            
            this.StratagemApplyed = false;
            if (this.CurrentStratagem != null)
            {
                this.DecreaseCombativity(this.CurrentStratagem.Combativity - this.DecrementOfStratagemCombativityConsuming);
            }
            this.SetOutburst();
            if ((((this.CurrentStunt != null) && (this.StuntDayLeft > 0)) || (this.CurrentCombatMethod != null)) || (this.CurrentOutburstKind != OutburstKind.无))
            {
                this.RefreshAllData();
            }
            if (this.RecentlyFighting > 0)
            {
                this.RecentlyFighting--;
            }
        }

