        /// <summary>
        /// 🆕 应用势力范围增益（基于能量分级）
        /// 🧊 Cold Path：部队移动或势力范围更新时调用
        /// 日期：2026-03-16
        /// </summary>
        public void MarkInfluenceBuffNeedsBootstrapFromSave()
        {
            _needsInfluenceBuffBootstrapFromSave = true;
        }

        public bool ApplyInfluenceBuff()
        {
            // 🔥 ANTI-BAND-AID：检查数据源
            if (this.BelongedFaction == null)
            {
                // 无归属势力的部队（如野怪）不获得增益
                return false;
            }
            
            // 🔥 初始化顺序容错：GlobalInfluenceMap 在 InfluenceUpdateManager.Initialize() 中初始化
            // 🔥 日期：2026-03-17
            // 🔥 场景：AfterLoadGameScenario() 在 GlobalInfluenceMap 初始化前调用
            if (this.BelongedFaction.GlobalInfluenceMap is not { Length: > 0 })
            {
                // 跳过增益应用，等待 InfluenceUpdateManager.Initialize() 完成后再次调用
                return false;
            }
            
            // 1. 获取当前位置的净能量
            int netEnergy = WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.GetNetInfluenceAt(
                this.Position, 
                this.BelongedFaction);
            
            // 2. 计算本次应应用的增量
            float attackMultiplier = WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.CalculateAttackBonus(netEnergy, isArchitecture: false);
            float newOffenceDelta = attackMultiplier > 1.0f ? attackMultiplier - 1.0f : 0f;

            float defenseMultiplier = WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.CalculateDefenseBonus(netEnergy, isArchitecture: false);
            float newDefenceDelta = defenseMultiplier > 1.0f ? defenseMultiplier - 1.0f : 0f;

            float oldOffenceDelta = _appliedInfluenceOffenceDelta;
            float oldDefenceDelta = _appliedInfluenceDefenceDelta;
            int newVisionDelta = WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.CalculateVisionRange(netEnergy, isArchitecture: false);
            int oldVisionDelta = _appliedInfluenceVisionDelta;
            int newEffectiveViewRadius = this.ViewRadius + newVisionDelta;
            bool hasStateChanged = oldOffenceDelta != newOffenceDelta ||
                oldDefenceDelta != newDefenceDelta ||
                oldVisionDelta != newVisionDelta ||
                _cachedEffectiveViewRadius != newEffectiveViewRadius;

            // 3. 读档兼容：旧存档里的 RateOfOffence/RateOfDefence 可能已包含一次能量增量
            if (!hasStateChanged && !_needsInfluenceBuffBootstrapFromSave)
            {
                return false;
            }

            if (_needsInfluenceBuffBootstrapFromSave)
            {
                this.RateOfOffence -= newOffenceDelta;
                this.RateOfDefence -= newDefenceDelta;
                _needsInfluenceBuffBootstrapFromSave = false;
            }

            // 4. 撤销旧增益，再应用新增益，保证幂等
            this.RateOfOffence -= oldOffenceDelta;
            this.RateOfDefence -= oldDefenceDelta;

            _appliedInfluenceOffenceDelta = newOffenceDelta;
            _appliedInfluenceDefenceDelta = newDefenceDelta;
            _appliedInfluenceVisionDelta = newVisionDelta;

            this.RateOfOffence += _appliedInfluenceOffenceDelta;
            this.RateOfDefence += _appliedInfluenceDefenceDelta;

            // 5. 更新视野缓存，并在半径变化时重建视野登记
            int oldEffectiveViewRadius = _cachedEffectiveViewRadius;
            _cachedEffectiveViewRadius = newEffectiveViewRadius;

            if (this.viewArea != null && oldEffectiveViewRadius != _cachedEffectiveViewRadius)
            {
                RefreshInfluenceViewArea();
            }

            // 6. 记录调试信息
            #if DEBUG
            if (oldOffenceDelta != _appliedInfluenceOffenceDelta ||
                oldDefenceDelta != _appliedInfluenceDefenceDelta ||
                oldVisionDelta != _appliedInfluenceVisionDelta)
            {
                System.Diagnostics.Debug.WriteLine(
                    $"[Troop.ApplyInfluenceBuff] 部队 {this.DisplayName} 刷新增益：" +
                    $"攻击+{_appliedInfluenceOffenceDelta * 100:F1}%，" +
                    $"防御+{_appliedInfluenceDefenceDelta * 100:F1}%，" +
                    $"视野={_cachedEffectiveViewRadius}");
            }
            #endif

            return hasStateChanged;
        }
        
        /// <summary>
        /// 🆕 获取动态视野范围（基于能量）
        /// 🧊 Cold Path：部队移动或查询视野时调用
        /// 日期：2026-03-16
        /// </summary>
        /// <returns>视野范围（格子数）</returns>
        public int GetDynamicVisionRange()
        {
            // 🔥 ANTI-BAND-AID：检查数据源
            if (this.BelongedFaction == null)
            {
                return 1; // 🔥 核心保护：无归属势力的部队至少有 1 格视野
            }
            
            // 获取当前位置的净能量
            int netEnergy = WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.GetNetInfluenceAt(
                this.Position, 
                this.BelongedFaction);
            
            // 计算视野范围（部队至少 1 格）
            return WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.CalculateVisionRange(netEnergy, isArchitecture: false);
        }
        
        /// <summary>
        /// 🆕 获取情报等级（基于能量）
        /// 🧊 Cold Path：情报查询时调用
        /// 日期：2026-03-16
        /// </summary>
        /// <returns>情报等级</returns>
        public InformationLevel GetDynamicInformationLevel()
        {
            // 🔥 ANTI-BAND-AID：检查数据源
            if (this.BelongedFaction == null)
            {
                return InformationLevel.无;
            }
            
            // 获取当前位置的净能量
            int netEnergy = WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.GetNetInfluenceAt(
                this.Position, 
                this.BelongedFaction);
            
            // 计算情报等级
            return WorldOfTheThreeKingdoms.GameManager.InfluenceBuffCalculator.CalculateInformationLevel(netEnergy);
        }

        /// <summary>
        /// 更新部队的AI战术角色
        /// 使用懒加载机制：仅重置缓存，下次访问 CurrentRole 时自动重新计算
        /// </summary>
        public void UpdateRole()
        {
            // 使用懒加载缓存机制，仅重置缓存
            this.ResetRoleCache();
            
            // 立即触发一次重新计算（可选，确保日志输出）
            var role = this.CurrentRole;
            if (this.Leader != null)
            {
                System.Diagnostics.Debug.WriteLine($"[部队角色更新] {this.Leader.Name} 的部队角色更新为: {role} ({WorldOfTheThreeKingdoms.GameGlobal.AIRoleSelector.GetRoleDescription(role)})");
            }
        }

        private void RefreshAntiCriticalStrikeChance()
        {
            this.antiCriticalStrikeChance = SquareChance(this.TroopCommand, 0x3e8) + this.Leader.Calmness;
            this.antiCriticalStrikeChance += this.ChanceDecrementOfCriticalStrike;
            this.antiCriticalStrikeChance += this.ChanceDecrementOfCriticalStrikeByViewArea;
            if (this.BelongedFaction != null)
            {
                this.antiCriticalStrikeChance += this.BelongedFaction.IncrementOfAntiCriticalStrikeChance;
                if (this.CombatMethodApplied)
                {
                    switch (this.Army.Kind.Type)
                    {
                        case MilitaryType.步兵:
                            this.antiCriticalStrikeChance += this.BelongedFaction.AntiCriticalStrikeChanceIncrementWhileCombatMethodOfBubing;
                            break;

                        case MilitaryType.弩兵:
                            this.antiCriticalStrikeChance += this.BelongedFaction.AntiCriticalStrikeChanceIncrementWhileCombatMethodOfNubing;
                            break;

                        case MilitaryType.骑兵:
                            this.antiCriticalStrikeChance += this.BelongedFaction.AntiCriticalStrikeChanceIncrementWhileCombatMethodOfQibing;
                            break;

                        case MilitaryType.水军:
                            this.antiCriticalStrikeChance += this.BelongedFaction.AntiCriticalStrikeChanceIncrementWhileCombatMethodOfShuijun;
                            break;

                        case MilitaryType.器械:
                            this.antiCriticalStrikeChance += this.BelongedFaction.AntiCriticalStrikeChanceIncrementWhileCombatMethodOfQixie;
                            break;
                    }
                }
                this.antiCriticalStrikeChance += this.BelongedFaction.AntiCriticalOfMillitaryType[(int)this.Army.Kind.Type];
            }
        }

        private void RefreshAntiStratagemChanceIncrement()
        {
            this.antiStratagemChanceIncrement = this.ChanceDecrementOfStratagem;
            this.antiStratagemChanceIncrement += this.ChanceDecrementOfStratagemByViewArea;
            if (this.BelongedFaction != null)
            {
                this.antiStratagemChanceIncrement += this.BelongedFaction.IncrementOfResistStratagemChance;
                this.antiStratagemChanceIncrement += this.BelongedFaction.AntiStratagemOfMillitaryType[(int)this.Army.Kind.Type];
