        private ArchitectureDamage SendAttackDamage(Architecture architecture)
        {
            this.RecentlyFighting = 3;
            ArchitectureDamage damage = new ArchitectureDamage();
            damage.SourceTroop = this;
            damage.DestinationArchitecture = architecture;
            damage.Critical = GameObject.Chance(this.CriticalStrikeChance - (architecture.ChanceDecrementOfCriticalStrike));
            damage.Position = this.OrientationPosition;

            //int num = (int) (((((this.Offence * 10) * Session.Parameters.ArchitectureDamageRate) * this.ArchitectureDamageRate) * this.StuntArchitectureDamageRate) / ((float) architecture.Domination));
            int num = (int)(Math.Pow(this.Offence * this.ArchitectureDamageRate * this.StuntArchitectureDamageRate / ((float)architecture.Domination + 10), 0.62) * 1.16 * 10 * Session.Parameters.ArchitectureDamageRate);
            if (!Session.Current.Scenario.IsPlayer(this.BelongedFaction))
            {
                num = (int)(num * Session.Parameters.AIArchitectureDamageRate);
            }
            if (damage.Critical)
            {
                this.PreAction = TroopPreAction.暴击;
                num = (int)((num * 1.5f) * this.RateOfCriticalArchitectureDamage);
                if (architecture.Kind.HasDomination)
                {
                    damage.DominationDown = this.DominationDecrementOfCriticalStrike;
                }
                if (this.OnCriticalStrike != null)
                {
                    this.OnCriticalStrike(this, null);
                }
            }

            if (architecture.IsCapital)
            {
                num = (num * 2) / 3;
            }

            num = (int)(num * (1 - architecture.enduranceDecreaseRateDrop));

            damage.Damage = num;
            if (damage.Damage <= 0)
            {
                damage.Damage = 1;
            }
            if (damage.Damage > architecture.Endurance)
            {
                damage.Damage = architecture.Endurance;
            }

            if ((architecture.BelongedFaction != null) && !this.AirOffence)
            {
                damage.CounterDamage = (int)((((architecture.Endurance + architecture.Morale) * this.Army.Kind.ArchitectureCounterDamageRate) * 15f * architecture.RateOfArchitectureCounterDamage) / ((float)this.Defence));
                if (damage.CounterDamage > this.Quantity)
                {
                    damage.CounterDamage = this.Quantity;
                }
                damage.CounterInjury = (damage.CounterDamage * this.InjuryChance) / 100;
            }
            int num2 = (2 + (damage.Critical ? 1 : 0)) + (this.CombatMethodApplied ? 1 : 0);
            this.IncreaseAttackExperience(num2 * 2);
            ExtensionInterface.call("TroopSendArchitectureDamage", new Object[] { Session.Current.Scenario, this, damage, architecture });
            return damage;
        }

        /// <summary>
        /// 优化的伤害计算公式 - 恢复旧版幂次公式并保留安全防护
        /// </summary>
        private int CalculateOptimizedDamage(float offence, float defence)
        {
            try
            {
                // 1. 确保分母永远安全 (防止 debuff 或异常值导致除零)
                float safeDefence = MathF.Max(defence, 1f);

                // 2. 回退旧版幂次公式，使用 .NET 8 原生 MathF.Pow（单精度、AOT 友好）
                // 公式: (offence/defence)^0.62 * 1.16 * 500 * TroopDamageRate
                float damage = MathF.Pow(offence / safeDefence, 0.62f) * 1.16f * 500f * Session.Parameters.TroopDamageRate;

                // 3. 应用伤害补偿机制 - 因为战斗冷却跳过了一些帧，需要补偿伤害
                damage *= _accumulatedDamageMultiplier;

                // 4. 强制保底伤害 (防止高防单位完全无敌，导致战斗死循环)
                // 至少造成 1 点伤害
                return Math.Max(1, (int)damage);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[CalculateOptimizedDamage] 错误: {ex.Message}");
                // 出错时返回保底伤害
                return 1;
            }
        }

        /// <summary>
        /// 检查是否可以进行战斗 - 改进的战斗频率控制
        /// </summary>
        public bool CanBattle()
        {
            try
            {
                // 使用简单的时间戳作为帧计数器
                int currentFrame = Environment.TickCount / 16; // 假设60FPS，每帧约16ms

                return (currentFrame - _lastBattleFrame) >= BATTLE_COOLDOWN;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[CanBattle] 错误: {ex.Message}");
                return true; // 出错时允许战斗
            }
        }

        /// <summary>
        /// 检查是否可以对特定目标进行战斗 - 包含首次攻击逻辑
        /// </summary>
        public bool CanBattleTarget(Troop target)
        {
            try
            {
                if (target == null) return false;

                // 检测目标变化或首次进入战斗
                bool targetChanged = (_lastTarget != target);
                bool isFirstStrike = _justEnteredCombat || targetChanged;

                // 首次攻击总是允许的
                if (isFirstStrike) return true;

                // 否则检查常规冷却
                return CanBattle();
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[CanBattleTarget] 错误: {ex.Message}");
                return true; // 出错时允许战斗
            }
        }

        /// <summary>
        /// 智能战斗状态更新 - 支持首次攻击和冷却机制
        /// </summary>
        private bool ShouldSkipBattleThisFrame(Troop target)
        {
            try
            {
                if (target == null) return true;

                // 使用简单的时间戳作为帧计数器
                int currentFrame = Environment.TickCount / 16; // 假设60FPS，每帧约16ms

                // 检测目标变化或首次进入战斗
                bool targetChanged = (_lastTarget != target);
                bool isFirstStrike = _justEnteredCombat || targetChanged;

                // 更新目标记录
                _lastTarget = target;

                // 如果是刚接触敌人的第一帧，无视冷却，立刻计算一次
                // 这样反应最快，提供最佳的战斗体验
                if (isFirstStrike)
                {
                    _justEnteredCombat = false;
                    _lastBattleFrame = currentFrame;
                    _accumulatedDamageMultiplier = 1.0f; // 首次攻击不需要补偿
                    return false; // 立即执行战斗
                }

                // 常规冷却检查 - 使用 ID 错峰（防止所有单位都在第 5 帧同时计算，造成 CPU 峰值）
                bool isCoolingDown = (currentFrame + this.ID) % BATTLE_COOLDOWN != 0;
                if (isCoolingDown)
                {
                    return true; // 跳过这一帧的战斗
                }

                // 计算伤害补偿倍数
                // 因为我们休息了 BATTLE_COOLDOWN 帧，所以这一击要打出 BATTLE_COOLDOWN 帧的伤害量
                int framesSinceLastBattle = currentFrame - _lastBattleFrame;
                if (framesSinceLastBattle > 0 && framesSinceLastBattle <= BATTLE_COOLDOWN * 2)
                {
                    _accumulatedDamageMultiplier = Math.Min(BATTLE_COOLDOWN, framesSinceLastBattle);
                }
                else
                {
                    _accumulatedDamageMultiplier = BATTLE_COOLDOWN;
                }

                _lastBattleFrame = currentFrame;
                return false; // 执行战斗
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ShouldSkipBattleThisFrame] 错误: {ex.Message}");
                return false; // 出错时执行战斗
            }
        }

        /// <summary>
        /// 更新战斗状态 - 管理进入和离开战斗的状态变化
        /// </summary>
        private void UpdateBattleState(Troop target)
        {
            try
            {
                if (target != null && IsInAttackRange(target))
                {
                    // 如果有目标且在攻击范围内，但之前没有目标，标记为刚进入战斗
                    if (_lastTarget == null || _lastTarget != target)
                    {
                        _justEnteredCombat = true;
                    }
                }
                else
                {
                    // 离开战斗状态，重置标记
                    _justEnteredCombat = true; // 下次进入战斗时会被视为首次攻击
                    _lastTarget = null;
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[UpdateBattleState] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 检查是否在攻击范围内 - 辅助方法
        /// </summary>
        private bool IsInAttackRange(Troop target)
        {
            try
            {
                if (target == null) return false;

                float distance = Vector2.Distance(
                    new Vector2(this.Position.X, this.Position.Y),
                    new Vector2(target.Position.X, target.Position.Y)
                );

                // 🔥 使用 EffectiveViewRadius 而不是 ViewRadius
                // 日期：2026-03-16
                return distance <= this.EffectiveViewRadius; // 使用有效视野范围作为攻击范围
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[IsInAttackRange] 错误: {ex.Message}");
                return false;
            }
        }

        /// <summary>
        /// 检查是否应该显示伤害数字 - LOD（细节层次）优化
        /// </summary>
        private bool ShouldShowDamageNumber()
        {
            try
            {
                // 获取主游戏屏幕和鼠标位置
                var mainGameScreen = Session.MainGame?.mainGameScreen;
                if (mainGameScreen == null) return false;

                // 获取屏幕中心和鼠标位置
                Point screenCenter = new Point(mainGameScreen.viewportSize.X / 2, mainGameScreen.viewportSize.Y / 2);
                Point mousePosition = mainGameScreen.MousePosition;

                // 将部队世界坐标转换为屏幕坐标
                Point troopScreenPos = mainGameScreen.GetPointByPosition(this.Position);

                // 计算到屏幕中心的距离
                float distanceToCenter = Vector2.Distance(
                    new Vector2(troopScreenPos.X, troopScreenPos.Y),
                    new Vector2(screenCenter.X, screenCenter.Y)
                );

                // 计算到鼠标的距离
                float distanceToMouse = Vector2.Distance(
                    new Vector2(troopScreenPos.X, troopScreenPos.Y),
                    new Vector2(mousePosition.X, mousePosition.Y)
                );

                // LOD规则：
                // 1. 鼠标附近150像素内的单位总是显示
                // 2. 屏幕中心300像素内的单位显示
                // 3. 屏幕边缘的单位不显示
                const float MOUSE_PRIORITY_RADIUS = 150f;
                const float SCREEN_CENTER_RADIUS = 300f;

                return (distanceToMouse <= MOUSE_PRIORITY_RADIUS) ||
                       (distanceToCenter <= SCREEN_CENTER_RADIUS);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ShouldShowDamageNumber] 错误: {ex.Message}");
                return true; // 出错时默认显示
            }
        }



        /// <summary>
        /// 智能伤害数字显示 - 结合累积阈值和LOD
        /// </summary>
        private void ShowDamageNumberIfNeeded(float damage)
        {
            try
            {
                // 1. 累积伤害
                _accumulatedDisplayDamage += damage;

                // 2. 检查累积阈值
                float maxHP = Math.Max(this.Army?.Scale ?? 1000, 1000); // 默认1000作为基准
                bool exceedsPercentThreshold = _accumulatedDisplayDamage >= (maxHP * DAMAGE_DISPLAY_THRESHOLD_PERCENT);
                bool exceedsAbsoluteThreshold = _accumulatedDisplayDamage >= DAMAGE_DISPLAY_THRESHOLD_ABSOLUTE;

                if (!exceedsPercentThreshold && !exceedsAbsoluteThreshold)
                {
                    return; // 累积伤害不足，不显示
                }

                // 3. 检查LOD（细节层次）
                if (!ShouldShowDamageNumber())
                {
                    return; // 不在显示范围内，不显示
                }

                // 4. 显示累积的伤害数字并重置累积器
                float damageToShow = _accumulatedDisplayDamage;
                _accumulatedDisplayDamage = 0f; // 重置累积器
                DisplayDamageNumber(damageToShow);
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ShowDamageNumberIfNeeded] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 显示伤害数字 - 实际的显示逻辑
