            }
        }

        /// <summary>
        /// 【关键优化】核心 AI 入口
        /// </summary>
        public void ProcessAI()
        {
            // 1. 状态检查（保留你原有的）
            if (Destroyed || !Controllable) return;
            if (this.Status == TroopStatus.混乱 ||
                this.Status == TroopStatus.挑衅 ||
                this.Status == TroopStatus.伪报 ||
                this.Status == TroopStatus.埋伏) return;

            // 2. 【频率锁】如果冷却未到，直接跳过
            // 这能减少 98% 的 CPU 开销
            if (_aiCooldownCounter > 0)
            {
                _aiCooldownCounter--;
                return;
            }

            // 3. 重置冷却
            // 设置为 30-60 帧（0.5 - 1秒）执行一次，完全够用
            // 加上随机数，防止所有部队在同一帧醒来造成周期性卡顿
            _aiCooldownCounter = _rng.Next(30, 60);

            // 4. 执行原有逻辑（现在它是安全的了）
            try
            {
                switch (TroopStatus)
                {
                    case TroopStatus.行军:
                        ProcessMovementAI();
                        break;
                    case TroopStatus.攻击:
                        ProcessCombatAI();
                        break;
                    // ... 其他状态
                    default:
                        ProcessDefaultAI();
                        break;
                }
            }
            catch (Exception ex)
            {
                // 防止单个部队报错导致游戏崩溃
                if (AIManager.EnableDebugLog)
                    System.Diagnostics.Debug.WriteLine($"[Troop Error] ID:{ID} - {ex.Message}");
            }
        }

        /// <summary>
        /// 移动AI逻辑 - 性能优化版本
        /// </summary>
        private void ProcessMovementAI()
        {
            try
            {
                // ?? 性能优化：减少寻路调用
                // 检查是否有目标建筑
                if (WillArchitecture != null)
                {
                    // 🔧 修复：统一使用 _currentPath 字段
                    if (!HasPath || _currentPath == null || _currentPath.Count == 0)
                    {
                        // ?? 关键优化：使用简单直线路径而不是复杂A*寻路
                        GenerateSimplePathOptimized();
                    }
                }

                // ?? 性能优化：降低敌军检查频率
                // 只在特定条件下检查附近敌军
                if ((ID + _aiCooldownCounter) % 180 == 0) // 每3秒检查一次
                {
                    CheckForNearbyEnemies();
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ProcessMovementAI] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 战斗AI逻辑 - 性能优化版本
        /// </summary>
        private void ProcessCombatAI()
        {
            try
            {
                // ?? 性能优化：降低目标搜索频率
                // 只在特定帧执行复杂的目标搜索
                if ((ID + _aiCooldownCounter) % 120 == 0) // 每2秒搜索一次
                {
                    // 寻找最佳攻击目标
                    Troop bestTarget = FindBestAttackTargetOptimized();

                    if (bestTarget != null)
                    {
                        // 设置攻击目标
                        if (TargetTroop != bestTarget)
                        {
                            TargetTroop = bestTarget;
                        }
                    }
                }

                // 检查当前目标
                if (TargetTroop != null && !TargetTroop.Destroyed)
                {
                    // 检查攻击距离
                    if (IsInAttackRange(TargetTroop))
                    {
                        // 执行攻击逻辑（已有的战斗系统会处理）
                        // 这里只需要确保目标正确设置
                    }
                    else
                    {
                        // ?? 性能优化：使用简化移动而不是复杂寻路
                        MoveTowardsTargetOptimized(TargetTroop);
                    }
                }
                else
                {
                    // 没有目标，切换到行军状态
                    TroopStatus = TroopStatus.一般; // Use Normal to avoid engine block
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ProcessCombatAI] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 空闲AI逻辑
        /// </summary>
        private void ProcessIdleAI()
        {
            try
            {
                // 检查附近是否有敌军
                CheckForNearbyEnemies();

                // 如果有任务，切换到行军状态
                if (WillArchitecture != null || TargetTroop != null)
                {
                    TroopStatus = TroopStatus.一般; // Use Normal to avoid engine block
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[ProcessIdleAI] 错误: {ex.Message}");
            }
        }

