        /// <summary>
        /// 生成简单路径 - 性能优化版本
        /// </summary>
        private void GenerateSimplePathOptimized()
        {
            try
            {
                if (WillArchitecture == null) return;

                // 🔧 修复：使用新系统的 _currentPath 字段和 C# 12 集合表达式
                Point start = Position;
                Point end = WillArchitecture.Position;

                _currentPath = [start, end];
                _currentPathIndex = 0;

                HasPath = true;

                // 直接设置目标，让游戏引擎处理移动
                RealDestination = end;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[GenerateSimplePathOptimized] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 优化的目标搜索
        /// </summary>
        private Troop FindBestAttackTargetOptimized()
        {
            try
            {
                var hostileTroopsInView = this.GetHostileTroopsInView();
                if (hostileTroopsInView == null || hostileTroopsInView.Count == 0)
                    return null;

                // ?? 性能优化：只检查前几个敌军
                Troop bestTarget = null;
                float closestDistance = float.MaxValue;
                int maxCheck = Math.Min(5, hostileTroopsInView.Count);

                var troopList = hostileTroopsInView.GetList();
                for (int i = 0; i < maxCheck; i++)
                {
                    if (troopList[i] is Troop enemy && enemy != null && !enemy.Destroyed)
                    {
                        // 使用简化的距离计算（避免开方运算）
                        int dx = Position.X - enemy.Position.X;
                        int dy = Position.Y - enemy.Position.Y;
                        float distanceSquared = dx * dx + dy * dy;

                        if (distanceSquared < closestDistance)
                        {
                            closestDistance = distanceSquared;
                            bestTarget = enemy;
                        }
                    }
                }

                return bestTarget;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[FindBestAttackTargetOptimized] 错误: {ex.Message}");
                return null;
            }
        }

        /// <summary>
        /// 优化的移动方法
        /// </summary>
        private void MoveTowardsTargetOptimized(Troop target)
        {
            try
            {
                if (target == null) return;

                // 🔧 修复：使用新系统的 _currentPath 字段和 C# 12 集合表达式
                Point targetPos = target.Position;
                RealDestination = targetPos;

                // 清除复杂路径，让游戏引擎使用简单移动
                _currentPath = [Position, targetPos];
                _currentPathIndex = 0;
                HasPath = true;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[MoveTowardsTargetOptimized] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 检查附近敌军
        /// </summary>
        private void CheckForNearbyEnemies()
        {
            try
            {
                // 这里可以集成现有的敌军检测逻辑
                // 简化版本：检查视野内的敌对部队
                var hostileTroopsInView = this.GetHostileTroopsInView();
                if (hostileTroopsInView != null && hostileTroopsInView.Count > 0)
                {
                    // 发现敌军，切换到攻击状态
                    if (TroopStatus != TroopStatus.攻击)
                    {
                        TroopStatus = TroopStatus.一般; // Use Normal to avoid engine block, but TargetTroop is already set
                    }
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[CheckForNearbyEnemies] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 寻找最佳攻击目标
        /// </summary>
        private Troop FindBestAttackTarget()
        {
            try
            {
                var hostileTroopsInView = this.GetHostileTroopsInView();
                if (hostileTroopsInView == null || hostileTroopsInView.Count == 0)
                    return null;

                Troop bestTarget = null;
                float closestDistance = float.MaxValue;

                foreach (Troop enemy in hostileTroopsInView.GetList())
                {
                    if (enemy == null || enemy.Destroyed) continue;

                    float distance = Vector2.DistanceSquared(
                        new Vector2(Position.X, Position.Y),
                        new Vector2(enemy.Position.X, enemy.Position.Y)
                    );

                    if (distance < closestDistance)
                    {
                        closestDistance = distance;
                        bestTarget = enemy;
                    }
                }

                return bestTarget;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[FindBestAttackTarget] 错误: {ex.Message}");
                return null;
            }
        }

        /// <summary>
        /// 向目标移动 - 增强版分层寻路
        /// </summary>
        private void MoveTowardsTarget(Troop target)
        {
            try
            {
                if (target == null) return;

                Point targetPos = target.Position;

                // 检查是否需要重新计算路径
                bool needNewPath = !HasValidPath ||
                                   !_lastPathTarget.Equals(targetPos) ||
                                   (DateTime.Now - _lastPathCalculation).TotalSeconds > PATH_RECALCULATION_INTERVAL;

                if (needNewPath)
                {
                    CalculatePathToTarget(targetPos);
                }

                // 跟随当前路径
                FollowCurrentPath();
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[MoveTowardsTarget] 错误: {ex.Message}");
                // 回退到简单移动
                FallbackToSimpleMovement(target);
            }
        }

        /// <summary>
        /// 计算到目标的路径
        /// </summary>
        private void CalculatePathToTarget(Point targetPos)
        {
            try
            {
                // 使用分层寻路系统
                var pathfindingManager = WorldOfTheThreeKingdoms.GameManager.PathfindingManager.Instance;
                if (pathfindingManager != null)
                {
                    var newPath = pathfindingManager.FindPath(Position, targetPos, true);

                    if (newPath != null && newPath.Count > 0)
                    {
                        _currentPath = newPath;
                        _currentPathIndex = 0;
                        _lastPathTarget = targetPos;
                        _lastPathCalculation = DateTime.Now;

                        System.Diagnostics.Debug.WriteLine($"[Troop {ID}] 计算新路径: {Position} -> {targetPos}, 长度: {newPath.Count}");
                    }
                    else
                    {
                        // 寻路失败，清空路径
                        ClearCurrentPath();
                        System.Diagnostics.Debug.WriteLine($"[Troop {ID}] 寻路失败: {Position} -> {targetPos}");
                    }
                }
                else
                {
                    // 寻路管理器未初始化，清空路径
                    ClearCurrentPath();
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[CalculatePathToTarget] 错误: {ex.Message}");
                ClearCurrentPath();
            }
        }

        /// <summary>
        /// 跟随当前路径移动
        /// </summary>
        private void FollowCurrentPath()
        {
            try
            {
                if (!HasValidPath) return;

                Point currentTarget = _currentPath[_currentPathIndex];

                // 检查是否到达当前路径点
                int distanceSquared = GetDistanceSquared(Position, currentTarget);
                if (distanceSquared <= PATH_FOLLOWING_TOLERANCE * PATH_FOLLOWING_TOLERANCE)
                {
                    // 到达当前路径点，移动到下一个
                    _currentPathIndex++;

                    if (_currentPathIndex >= _currentPath.Count)
                    {
                        // 路径完成
                        ClearCurrentPath();
                        return;
                    }

                    currentTarget = _currentPath[_currentPathIndex];
                }

                // 设置目标为当前路径点
                Destination = currentTarget;
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[FollowCurrentPath] 错误: {ex.Message}");
                ClearCurrentPath();
            }
        }

        /// <summary>
        /// 回退到简单移动逻辑
        /// </summary>
        private void FallbackToSimpleMovement(Troop target)
        {
            try
            {
                if (target == null) return;

                Point targetPos = target.Position;

                // 简单的移动逻辑 - 直接朝目标移动
                int deltaX = targetPos.X - Position.X;
                int deltaY = targetPos.Y - Position.Y;

                // 标准化移动方向
                if (Math.Abs(deltaX) > Math.Abs(deltaY))
                {
                    Destination = new Point(Position.X + Math.Sign(deltaX), Position.Y);
                }
                else
                {
                    Destination = new Point(Position.X, Position.Y + Math.Sign(deltaY));
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[FallbackToSimpleMovement] 错误: {ex.Message}");
            }
        }

        /// <summary>
        /// 清空当前路径
        /// </summary>
        private void ClearCurrentPath()
        {
            _currentPath = null;
            _currentPathIndex = 0;
            _lastPathTarget = Point.Zero;
        }

        /// <summary>
        /// 计算两点间距离的平方（避免开方运算）
        /// </summary>
        private int GetDistanceSquared(Point a, Point b)
        {
            int dx = a.X - b.X;
            int dy = a.Y - b.Y;
            return dx * dx + dy * dy;
        }

        /// <summary>
        /// 异步计算路径 - 用于大规模部队移动
        /// </summary>
        public void CalculatePathAsync(Point targetPos, Action<bool> callback = null)
        {
            try
            {
                var pathfindingManager = WorldOfTheThreeKingdoms.GameManager.PathfindingManager.Instance;
                if (pathfindingManager != null)
                {
                    pathfindingManager.FindPathAsync(Position, targetPos, (path) =>
                    {
                        try
                        {
                            if (path != null && path.Count > 0)
                            {
                                _currentPath = path;
                                _currentPathIndex = 0;
                                _lastPathTarget = targetPos;
                                _lastPathCalculation = DateTime.Now;

                                callback?.Invoke(true);
                                System.Diagnostics.Debug.WriteLine($"[Troop {ID}] 异步路径计算完成: 长度 {path.Count}");
                            }
                            else
                            {
                                ClearCurrentPath();
                                callback?.Invoke(false);
                                System.Diagnostics.Debug.WriteLine($"[Troop {ID}] 异步寻路失败");
                            }
                        }
                        catch (Exception ex)
                        {
                            System.Diagnostics.Debug.WriteLine($"[CalculatePathAsync回调] 错误: {ex.Message}");
                            callback?.Invoke(false);
                        }
                    });
                }
                else
                {
                    callback?.Invoke(false);
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[CalculatePathAsync] 错误: {ex.Message}");
                callback?.Invoke(false);
            }
        }

        // ====== 新异步寻路系统方法（任务 10）======

        /// <summary>
        /// 请求异步寻路（仅新系统）
        /// 🔥 Hot Path - 主线程调用，必须非阻塞（< 10μs）
        /// </summary>
        /// <summary>
        /// 【新异步系统】发起异步寻路请求
        /// </summary>
        /// <param name="target">目标位置</param>
        public void RequestMoveAsync(Point target)
        {
            // 1. 清理旧任务
            CancelCurrentPathfinding();

            // 2. 原子操作自增版本号（绝对线程安全，性能极高）
            _pathTrackingId = Interlocked.Increment(ref _globalPathTrackingCounter);
            _moveCts = new CancellationTokenSource();
            _isWaitingForPath = true;
            _isPathfinding = true;

            // 3. 获取地形适应性快照（避免后台线程访问主线程数据）
            // 🔥 反创可贴协议：如果 Army 或 Kind 为 null，说明数据初始化有问题
            // 这里崩溃是正确的，便于追踪数据源错误
            var terrainCosts = new GameObjects.AI.Pathfinding.TerrainCostProfile(
                this.GetTerrainAdaptability(TerrainKind.平原),
                this.GetTerrainAdaptability(TerrainKind.草原),
                this.GetTerrainAdaptability(TerrainKind.森林),
                this.GetTerrainAdaptability(TerrainKind.湿地),
                this.GetTerrainAdaptability(TerrainKind.山地),
                this.GetTerrainAdaptability(TerrainKind.水域),
                this.GetTerrainAdaptability(TerrainKind.峻岭),
                this.GetTerrainAdaptability(TerrainKind.荒地),
                this.GetTerrainAdaptability(TerrainKind.沙漠),
                this.GetTerrainAdaptability(TerrainKind.栈道)
            );

            var scenario = Session.Current.Scenario;
            GameObjects.AI.Pathfinding.AsyncPathfindingManager.Instance.EnsureTerrainSnapshot(scenario);
            bool targetHasArchitecture = scenario.GetArchitectureByPosition(target) != null;
            var mapData = scenario.ScenarioMap.MapData ?? throw new InvalidOperationException("ScenarioMap.MapData 为 null，无法构建异步寻路快照。");
            var penalizedMapData = scenario.PenalizedMapData ?? throw new InvalidOperationException("Scenario.PenalizedMapData 为 null，无法构建异步寻路快照。");
            int mapWidth = scenario.ScenarioMap.MapDimensions.X;
            int mapHeight = scenario.ScenarioMap.MapDimensions.Y;
            int nodeCount = mapWidth * mapHeight;
            var traversalCosts = System.Buffers.ArrayPool<int>.Shared.Rent(nodeCount);
            var traversalPenalties = System.Buffers.ArrayPool<int>.Shared.Rent(nodeCount);
            var obstacles = System.Buffers.ArrayPool<GameObjects.AI.Pathfinding.DynamicObstacle>.Shared.Rent(1);
            int obstacleCount = 0;
            bool requestQueued = false;

            try
            {
                static int CombinePenalty(int currentPenalty, int addedPenalty, int unreachableCost)
                {
                    if (addedPenalty >= unreachableCost)
                    {
                        return unreachableCost;
                    }

                    int mergedPenalty = currentPenalty + addedPenalty;
                    return mergedPenalty >= unreachableCost ? unreachableCost : mergedPenalty;
                }

                static GameManager.UnitType GetUnitType(MilitaryType militaryType) => militaryType switch
                {
                    MilitaryType.步兵 => GameManager.UnitType.步兵,
                    MilitaryType.弩兵 => GameManager.UnitType.弓兵,
                    MilitaryType.骑兵 => GameManager.UnitType.骑兵,
                    MilitaryType.器械 => GameManager.UnitType.攻城器械,
                    MilitaryType.水军 => GameManager.UnitType.水军,
                    _ => GameManager.UnitType.步兵
                };

                static GameManager.TerrainType GetTerrainType(int terrainId) => terrainId switch
                {
                    1 or 2 => GameManager.TerrainType.Plain,
                    3 => GameManager.TerrainType.Forest,
                    4 or 6 => GameManager.TerrainType.River,
                    5 or 7 => GameManager.TerrainType.Mountain,
                    _ => GameManager.TerrainType.Other
                };

                const int unreachableCost = GameObjects.AI.Pathfinding.TerrainCostProfile.UnreachableTerrainCost;
                MilitaryKind kind = this.Army.Kind;
                var unitType = GetUnitType(kind.Type);

                for (int y = 0; y < mapHeight; y++)
                {
                    int rowOffset = y * mapWidth;
                    for (int x = 0; x < mapWidth; x++)
                    {
                        Point pos = new(x, y);
                        int index = rowOffset + x;
                        int cost = this.GetCostByPosition(pos, false, -1, kind);
                        int traversalPenalty = 0;

                        if (cost < unreachableCost)
                        {
                            var terrainType = GetTerrainType(mapData[x, y]);
                            traversalPenalty = WorldOfTheThreeKingdoms.GameLogic.MovementCostCalculator.GetWeatherPenalty(
                                pos,
                                unitType,
                                terrainType);

                            int penalizedCost = penalizedMapData[x, y];
                            if (penalizedCost > 0)
                            {
                                traversalPenalty = CombinePenalty(traversalPenalty, penalizedCost, unreachableCost);
                            }

                            int temporaryPenalty = scenario.GetTemporaryPenalty(pos);
                            if (temporaryPenalty > 0)
                            {
                                traversalPenalty = CombinePenalty(traversalPenalty, temporaryPenalty, unreachableCost);
                            }
                        }

                        traversalCosts[index] = cost;
                        traversalPenalties[index] = traversalPenalty;
                    }
                }

                // 5. 构建请求（纯值类型快照）
                var request = new GameObjects.AI.Pathfinding.PathRequest(
                    this.Id,
                    _pathTrackingId,
                    this.Position,
                    target,
                    terrainCosts,
                    targetHasArchitecture,
                    traversalCosts,
                    nodeCount,
                    traversalPenalties,
                    nodeCount,
                    obstacles,
                    obstacleCount,
                    _moveCts.Token
                );

                // 6. 入队到全局管理器（非阻塞）
                GameObjects.AI.Pathfinding.AsyncPathfindingManager.Instance.EnqueueRequest(request);
                requestQueued = true;

                #if DEBUG
                System.Diagnostics.Debug.WriteLine($"[RequestMoveAsync] {this.DisplayName} 请求寻路: {this.Position} → {target}，TrackingId={_pathTrackingId}");
                #endif
            }
            finally
            {
                if (!requestQueued)
                {
                    System.Buffers.ArrayPool<int>.Shared.Return(traversalCosts, clearArray: false);
                    System.Buffers.ArrayPool<int>.Shared.Return(traversalPenalties, clearArray: false);
                    System.Buffers.ArrayPool<GameObjects.AI.Pathfinding.DynamicObstacle>.Shared.Return(obstacles, clearArray: false);
                }
            }
        }


        /// <summary>
        /// 取消当前寻路任务
        /// 🔥 Hot Path - 可能在每帧调用，必须高效
        /// </summary>
        public void CancelCurrentPathfinding()
        {
            // 通过状态标志判断，而不是空检查（反创可贴协议）
            // 如果没有正在进行的寻路，直接返回
            if (!_isWaitingForPath) return;

            // 此时 _moveCts 必定不为 null（由 RequestMoveAsync 保证）
            // 如果这里崩溃，说明状态不一致，需要修复 RequestMoveAsync
            _moveCts.Cancel();
            _moveCts.Dispose();
            _moveCts = null;
            _isWaitingForPath = false;
            _isPathfinding = false;

            System.Diagnostics.Debug.WriteLine($"[Troop] {this.DisplayName} 取消寻路任务");
        }

        private void CancelLegacyMoveTask()
        {
            if (_oldSystemMoveCts == null) return;

            _oldSystemMoveCts.Cancel();
            _oldSystemMoveCts.Dispose();
            _oldSystemMoveCts = null;
        }

        /// <summary>
        /// 【新异步系统】主线程回调：接收寻路结果
        /// 由 Session.Update 统一分发
        /// </summary>
        /// <param name="result">寻路结果</param>
        public void OnPathfindingCompleted(GameObjects.AI.Pathfinding.PathResult result)
        {
            // 极致防御：版本号校验（防幽灵折返）
            if (result.TrackingId != _pathTrackingId)
            {
                #if DEBUG
                System.Diagnostics.Debug.WriteLine($"[OnPathfindingCompleted] {this.DisplayName} 收到过期结果，丢弃: 期望={_pathTrackingId}, 实际={result.TrackingId}");
                #endif
                GameObjects.AI.Pathfinding.PathPool.Return(result.Path);
                return;
            }

            // 解锁状态
            _isWaitingForPath = false;
            _isPathfinding = false;

            if (_moveCts != null)
            {
                _moveCts.Dispose();
                _moveCts = null;
            }

            if (result.IsCancelled)
            {
                GameObjects.AI.Pathfinding.PathPool.Return(result.Path);
                return;
            }

            if (result.IsSuccess)
            {
                // 🔥 Anti-Band-Aid：不检查 Path 是否为 null
                // 如果 IsSuccess == true 但 Path == null，说明 PathResult 构造时有问题
                // 让它崩溃，暴露数据源错误：寻路成功时必须提供有效路径
                
                // 回收旧路径
                GameObjects.AI.Pathfinding.PathPool.Return(_cachedPath);
                
                // 🔥 修复：移除路径起点（如果是当前位置）
                // 日期：2026-03-04
                // 原因：路径包含起点会导致 ExecutePathMove 第一步是"移动到当前位置"，原地踏步
                // 解决：与同步寻路逻辑保持一致，移除起点
                if (result.Path.Count > 0 && result.Path[0] == this.Position)
                {
                    result.Path.RemoveAt(0);
                }
                
                // 🔥 性能优化：直接传递路径，避免分配中间对象
                // 调用内部方法处理竞态条件检查
                OnPathfindingCompletedInternal(result.Path, true);
            }
            else
            {
                // 寻路失败
                OnPathfindingCompletedInternal(null, false);
            }
        }


        /// <summary>
        /// 获取路径调试信息
        /// </summary>
        public string GetPathDebugInfo()
        {
            if (!HasValidPath)
            {
                return $"Troop {ID}: 无路径";
            }

            return $"Troop {ID}: 路径 {_currentPathIndex}/{_currentPath.Count}, 目标: {CurrentPathTarget}, 最后计算: {_lastPathCalculation:HH:mm:ss}";
        }

        /// <summary>
        /// 更新LOD等级 - 基于距离摄像机的距离
        /// </summary>
        public void UpdateLODLevel(float distanceSquared)
        {
            try
            {
                // LOD距离阈值（平方距离）
                const float HIGH_LOD_THRESHOLD = 150f * 150f;
                const float MEDIUM_LOD_THRESHOLD = 300f * 300f;
                const float LOW_LOD_THRESHOLD = 600f * 600f;

                LODLevel newLevel;
                if (distanceSquared <= HIGH_LOD_THRESHOLD)
                {
                    newLevel = LODLevel.High;
                }
                else if (distanceSquared <= MEDIUM_LOD_THRESHOLD)
                {
                    newLevel = LODLevel.Medium;
                }
                else if (distanceSquared <= LOW_LOD_THRESHOLD)
                {
                    newLevel = LODLevel.Low;
                }
                else
                {
                    newLevel = LODLevel.VeryLow;
                }

                // 只在LOD等级真正改变时更新，避免不必要的操作
                if (CurrentLODLevel != newLevel)
                {
                    CurrentLODLevel = newLevel;
                }
            }
            catch (Exception ex)
            {
                System.Diagnostics.Debug.WriteLine($"[UpdateLODLevel] 错误: {ex.Message}");
                CurrentLODLevel = LODLevel.High; // 出错时使用高质量
            }
        }

        /// <summary>
        /// 获取天气对物理伤害的修正倍率（HOT PATH）
        /// 日期：2026-03-10
        /// 说明：根据攻击方兵种、双方天气计算伤害修正
        /// </summary>
        private float GetWeatherCombatMultiplier(MilitaryType attackerType, Troop target)
        {
            // 🔥 HOT PATH：无 LINQ，使用 for 循环
            // ANTI-BAND-AID：不使用 ?. 掩盖配置系统错误，让异常自然抛出
            var config = Session.Current.Scenario.EnvironmentConfig.WeatherCombat;
            
            // WeatherCombat 是可选配置，允许为 null
            if (config == null) return 1.0f;
            
            var modifiers = config.Modifiers;
            int modifierCount = modifiers.Count;
            if (modifierCount == 0) return 1.0f;
            
            // 获取双方天气（O(1) 数组访问）
            var attackerWeather = Session.Current.Scenario.WeatherManager.GetWeatherAt(this.Position);
            var targetWeather = Session.Current.Scenario.WeatherManager.GetWeatherAt(target.Position);
            
            string attackerTypeName = attackerType.ToString();
            string attackerWeatherName = attackerWeather.ToString();
            string targetWeatherName = targetWeather.ToString();
            
            // 🔥 HOT PATH：for 循环查找匹配规则
            for (int i = 0; i < modifierCount; i++)
            {
                var modifier = modifiers[i];
                
                // 匹配攻击方兵种
                if (modifier.AttackerType != attackerTypeName) continue;
                
                // 匹配攻击方天气（null 表示任意天气）
                if (modifier.AttackerWeather != null && modifier.AttackerWeather != attackerWeatherName) continue;
                
                // 匹配目标方天气（null 表示任意天气）
                if (modifier.TargetWeather != null && modifier.TargetWeather != targetWeatherName) continue;
                
                // 找到匹配规则
                return modifier.Multiplier;
            }
            
            return 1.0f;  // 默认无影响
        }

        private TroopDamage SendAttackDamage(Troop troop, bool counter)
        {
            this.RecentlyFighting = 3;
            troop.RecentlyFighting = 3;

            // 使用对象池获取TroopDamage对象，避免GC压力
            TroopDamage damage = global::GameManager.ObjectPoolManager.DamagePool.Get();
            damage.SourceTroop = this;
            damage.DestinationTroop = troop;
            damage.Counter = counter;
            damage.AntiAttack = GameObject.Chance(troop.ChanceOfBlockAttack);
            damage.AntiArrowAttack = this.ArrowOffence && (troop.IsAntiArrowAttack || GameObject.Chance(troop.ChanceOfBlockArrowAttack));
            damage.AntiCounterAttack = !counter && this.IsAntiCounterAttack;
            
            // 🔥 暴击诊断日志
            #if DEBUG
            int criticalChance = this.CriticalStrikeChance - troop.AntiCriticalStrikeChance;
            System.Diagnostics.Debug.WriteLine($"[暴击判定] 攻击方:{this.Leader?.Name}(统率:{this.TroopStrength},勇猛:{this.Leader?.Braveness}) 暴击率:{this.CriticalStrikeChance} | 防守方:{troop.Leader?.Name}(统率:{troop.TroopCommand},冷静:{troop.Leader?.Calmness}) 抗暴率:{troop.AntiCriticalStrikeChance} | 最终暴击率:{criticalChance} | 反击:{counter} | 爆发免暴:{troop.OutburstPreventCriticalStrike}");
            #endif
            
            damage.Critical = (!counter && !troop.OutburstPreventCriticalStrike) && (GameObject.Chance(this.ChanceOfMustCriticalStrike) || GameObject.Chance(this.CriticalStrikeChance - troop.AntiCriticalStrikeChance));
            damage.OnFire = GameObject.Chance((this.ChanceOfOnFire > this.BaseChanceOfOnFire) ? this.ChanceOfOnFire : this.BaseChanceOfOnFire);
            damage.Chaos = GameObject.Chance(this.ChanceOfChaosAttack);
            if (this.Status == TroopStatus.埋伏)
            {
                this.Status = TroopStatus.一般;
                damage.Waylay = true;
                if (!damage.Critical)
                {
                    this.PreAction = TroopPreAction.伏击;
                }
            }
            if (troop.Defence <= 0)
            {
                damage.Damage = troop.Quantity;
                return damage;
            }
            int defence = troop.Defence;
            if ((this.BaseDefenceConsidered > 0) && (this.DefenceConsidered > 0))
            {
                int num2 = (this.BaseDefenceConsidered < this.DefenceConsidered) ? this.BaseDefenceConsidered : this.DefenceConsidered;
                if (defence > num2)
                {
                    defence = num2;
                }
            }
            else if (this.BaseDefenceConsidered > 0)
            {
                if (defence > this.BaseDefenceConsidered)
                {
                    defence = this.BaseDefenceConsidered;
                }
            }
            else if (this.DefenceConsidered > 0)
            {
                if (defence > this.DefenceConsidered)
                {
                    defence = this.DefenceConsidered;
                }
            }
            else if (GameObject.Chance(this.ChanceOfFixDefenceAttack) && (defence > 100))
            {
                defence = 100;
            }
            damage.SourceOffence = this.Offence;

            Architecture troopArch = Session.Current.Scenario.GetArchitectureByPositionNoCheck(troop.Position);
            if (troopArch != null && troopArch.Endurance > 0)
            {
                damage.SourceOffence = (int)(damage.SourceOffence * (1 + this.InCityOffenseRate));
            }

            if ((!troop.StuntAvoidSurround && !counter) && (this.StuntMustSurround || !GameObject.Chance(troop.AvoidSurroundedChance)))
            {
                TroopList surroundAttackingTroop = this.GetSurroundAttackingTroop(troop);
                if (surroundAttackingTroop.Count >= 3)
                {
                    int num3 = 0;
                    damage.Surround = true;
                    damage.DestinationMoraleChange -= Session.GlobalVariables.SurroundFactor * ((surroundAttackingTroop.Count - 3) + 1);
                    troop.Effect = TroopEffect.被包围;
                    foreach (Troop troop2 in surroundAttackingTroop)
                    {
                        if (troop2 != this)
                        {
                            damage.SurroudingList.Add(troop2);
                            troop2.Surrounding = true;
                            damage.SourceOffence += StaticMethods.GetRandomValue(troop2.Offence, Session.GlobalVariables.SurroundFactor * 4 / 5);
                            num3 += StaticMethods.GetRandomValue(troop2.ChaosAfterSurroundAttackChance, Session.GlobalVariables.SurroundFactor * 2 / 5);
                        }
                    }
                    damage.Chaos = GameObject.Chance(this.ChaosAfterSurroundAttackChance + num3);
                }
            }
            // 优化后的伤害计算公式（恢复旧版幂次公式，内部包含安全防护）
            // 原始复杂公式: Math.Pow(damage.SourceOffence / (float)defence, 0.62) * 1.16 * 500 * Session.Parameters.TroopDamageRate
            int num4 = CalculateOptimizedDamage(damage.SourceOffence, defence);
            switch (troop.Army.Kind.Type)
            {
                case MilitaryType.步兵:
                    num4 = (int)(num4 * this.OffenceRateOnSubdueBubing);
                    break;

                case MilitaryType.弩兵:
                    num4 = (int)(num4 * this.OffenceRateOnSubdueNubing);
                    break;

                case MilitaryType.骑兵:
                    num4 = (int)((num4 * this.OffenceRateOnSubdueQibing) * ((this.RateOfQibingDamage > this.BaseRateOfQibingDamage) ? this.RateOfQibingDamage : this.BaseRateOfQibingDamage));
                    break;

                case MilitaryType.水军:
                    num4 = (int)(num4 * this.OffenceRateOnSubdueShuijun);
                    break;

                case MilitaryType.器械:
                    num4 = (int)(num4 * this.OffenceRateOnSubdueQixie);
                    break;
            }
            
            // 🔥 2026-03-10：天气对物理伤害的影响（HOT PATH）
            float weatherMultiplier = GetWeatherCombatMultiplier(this.Army.Kind.Type, troop);
            if (weatherMultiplier != 1.0f)
            {
                num4 = (int)(num4 * weatherMultiplier);
            }
            
            if (this.MoraleDownOfAttack > 0)
            {
                damage.DestinationMoraleChange -= this.MoraleDownOfAttack;
            }
            if (damage.OnFire)
            {
                int num5 = (int)((troop.Army.Kind.MinScale * Session.Parameters.FireDamageScale) * Session.Current.Scenario.GetTerrainDetailByPositionNoCheck(troop.Position).FireDamageRate);
                num5 = (int)(num5 * this.FireDamageRate);
                if (troop.RateOfFireProtection > 0f)
                {
                    num5 = (int)(num5 * troop.RateOfFireProtection);
                }
                damage.FireDamage = num5;
                damage.DestinationMoraleChange -= (int)(5 * troop.RateOfFireProtection + 1);
            }

            damage.InjuredDamage = (int)(this.reduceInjuredOnAttack * damage.DestinationTroop.Army.Kind.MinScale);
            damage.TirednessIncrease = this.TirednessIncreaseOnAttack;
            damage.StealFood = Math.Min(damage.DestinationTroop.Food, this.StealFood);
            //Challenge challenge = new Challenge();
            //challenge.ChallgenEvent(this, troop, damage);  //单挑事件
            if (damage.Critical) //控制单挑发生相关
            {
                this.PreAction = TroopPreAction.暴击;
                num4 = (int)((num4 * 1.5f) * troop.RateOfCriticalDamageReceived);
                if (!(damage.Chaos || !GameObject.Chance(this.ChaosAfterCriticalStrikeChance)))
                {
                    damage.Chaos = true;
                }
                if (this.MoraleDecrementOfCriticalStrike > 0)
                {
                    damage.DestinationMoraleChange -= this.MoraleDecrementOfCriticalStrike;
                }
                Challenge challenge = new Challenge();
                challenge.ChallgenEvent(this, troop, damage);  //单挑事件
                this.troopChallengeCommand = false;
                damage.InjuredDamage += (int)(this.reduceInjuredOnCritical * damage.DestinationTroop.Army.Kind.MinScale);
                damage.TirednessIncrease += this.TirednessIncreaseOnCritical;
            }
            if (this.troopChallengeCommand)
            {
                Challenge challenge = new Challenge();
                challenge.ChallgenEvent(this, troop, damage);
                this.troopChallengeCommand = false;
            }
            if (damage.Waylay)
            {
                damage.DestinationMoraleChange -= 10;
                if (troop.NeverBeIntoChaosWhileWaylay)
                {
                    damage.Chaos = false;
                }
                else if (!this.Army.Kind.AirOffence)
                {
                    damage.Chaos = this.InevitableChaosOnWaylay || GameObject.Chance(30);
                }
            }
            if (damage.Counter)
            {
                num4 = (int)(num4 * 0.5f);
            }
            if (!(counter || (this.AttackDecrementOfCombativity <= 0)))
            {
                damage.DestinationCombativityChange -= this.AttackDecrementOfCombativity;
            }
            if (counter && (this.CounterAttackDecrementOfCombativity > 0))
            {
                damage.CounterCombativityDown += this.CounterAttackDecrementOfCombativity;
            }
            if (!troop.HasCombatTitle)
            {
                if (this.CombativityDecrementOnPower > 0)
                {
                    damage.DestinationCombativityChange -= this.CombativityDecrementOnPower;
                }
                if (this.MoraleDecrementOnPrestige > 0)
                {
                    damage.DestinationMoraleChange -= this.MoraleDecrementOnPrestige;
                }
            }
            if (GameObject.Chance(this.ChanceOfTrippleDamage))
            {
                num4 *= 3;
            }
            else if (GameObject.Chance(this.ChanceOfDoubleDamage))
            {
                num4 *= 2;
            }
            if (GameObject.Chance(troop.ChanceOfHalfDamage))
            {
                num4 /= 2;
            }
            damage.Damage = num4;

            // 智能伤害数字显示优化 - 累积阈值和LOD系统
            ShowDamageNumberIfNeeded(num4);

            damage.StealTroop = Math.Min(damage.DestinationTroop.Quantity, (int)(damage.Damage * this.StealTroop));
            damage.StealInjured = Math.Min(damage.DestinationTroop.InjuryQuantity, (int)(damage.Damage * this.StealInjured));
            damage.OfficerInjury = 0;
            if ((damage.Critical || troop.Quantity <= damage.Damage) && damage.Damage > 0 && Session.GlobalVariables.OfficerDieInBattleRate > 0)
            {
                float dieChance = Session.GlobalVariables.OfficerDieInBattleRate / 10000.0f;
                if (troop.Quantity <= damage.Damage)
                {
                    dieChance *= 2;
                }
                if (damage.Surround)
                {
                    dieChance *= 1.5f;
                }
                if (damage.Waylay)
                {
                    dieChance *= 3;
                }
                dieChance *= (damage.SourceTroop.Leader.Strength + damage.SourceTroop.Leader.Braveness * 10
                    - damage.DestinationTroop.Leader.Strength - damage.DestinationTroop.Leader.Braveness * 10 + 100) / 100.0f;
                double rand = GameObject.Random(100000) / 100000.0;
                damage.OfficerInjury = (float)(dieChance / rand);
                if (damage.OfficerInjury < 0.1)
                {
                    damage.OfficerInjury = 0;
                }
            }

            damage.DestinationMoraleChange -= (int)(damage.Damage / 100.0f * ((75 - troop.Leader.Command) / 50 + 1));

            ExtensionInterface.call("TroopSendTroopDamage", new Object[] { Session.Current.Scenario, this, damage, troop, counter });
            return damage;
        }

