                    }
                    return TroopControlState.Done;
                }
                if (this.Auto)
                {
                    return TroopControlState.Auto;
                }
                if (this.SelectedAttack)
                {
                    return TroopControlState.Attacked;
                }
                if (this.SelectedMove)
                {
                    return TroopControlState.Moved;
                }
                return TroopControlState.Undone;
            }
        }

