        /// <summary>
        /// 获取部队当前实际的视野半径（受能量影响）
        /// 日期：2026-03-10（天气系统）
        /// 日期：2026-03-16（整合能量系统）
        /// 日期：2026-03-20（移除天气硬编码，完全依赖能量）
        /// 🔥 HOT PATH：每帧可能被调用多次，使用内联优化 + 配置缓存
        /// 
        /// 说明：视野完全由能量决定，天气通过影响能量扩散间接影响视野
        /// </summary>
        public int EffectiveViewRadius
        {
            get
            {
                // 🔥 Phase 3.2：整合能量增益
                // 基础视野 = ViewRadius + 能量增益（来自缓存）
                int baseRadius = this.ViewRadius;
                
                // 添加能量增益（如果缓存已初始化）
                if (_cachedEffectiveViewRadius >= 0)
                {
                    // 使用缓存的有效视野（包含能量增益）
                    baseRadius = _cachedEffectiveViewRadius;
                }
                
                // 🆕 2026-03-20：移除天气硬编码
                // 原因：视野应该完全由能量决定，天气通过影响能量扩散间接影响视野
                // 恶劣天气（雾、雨、雪）会降低部队能量扩散范围，从而自然降低视野
                
                // 保底机制：视野至少为 1（防止寻路或渲染崩溃）
                return Math.Max(1, baseRadius);
            }
        }
        [DataMember]
        public int WaitForDeepChaosFrameCount
        {
            get
            {
                return this.waitForDeepChaosFrameCount;
            }
            set
            {
                this.waitForDeepChaosFrameCount = value;
                if (((value == 0) && this.WaitForDeepChaos) && ((this.OrientationTroop != null) && !this.OrientationTroop.Destroyed))
                {
                    if (this.OnCastDeepChaos != null)
                    {
                        this.OnCastDeepChaos(this, this.OrientationTroop);
                    }
                    this.PreAction = TroopPreAction.致乱;
                    this.Action = TroopAction.Cast;
                    this.OrientationTroop.Action = TroopAction.BeCasted;
                }
            }
        }

