        public float InfluenceKindValue(int id)
        {
            float result = 0;
            foreach (Influence i in Session.Current.Scenario.GameCommonData.AllInfluences.Influences.Values)
            {
                if (i.Kind.ID == id)
                {
                    foreach (ApplyingTroop j in i.appliedTroop)
                    {
                        if (j.troop == this)
                        {
                            result += i.Value;
                        }
                    }
                }
            }
            return result;
        }
